/**
 * Export/import envelopes and sanitized bulk run exports.
 */

import type {
  BulkExportEnvelope,
  BulkManifest,
  BulkRunCheckpoint,
} from '../../types/bulkOperationsPlanner';
import {
  BULK_MANIFEST_FORMAT_KIND,
  BULK_MANIFEST_SCHEMA_VERSION,
} from '../../types/bulkOperationsPlanner';
import { verifyManifestChecksum } from './planner';
import { validateManifestOperations } from './validation';

export function exportManifestEnvelope(
  manifest: BulkManifest,
  checkpoint?: BulkRunCheckpoint,
  sanitized = true
): BulkExportEnvelope {
  const payload: BulkManifest = sanitized
    ? {
        ...manifest,
        operations: manifest.operations.map((op) => ({
          ...op,
          metadata: {
            ...op.metadata,
            notes: op.metadata.notes ? '[REDACTED]' : undefined,
          },
        })),
      }
    : manifest;

  return {
    formatKind: BULK_MANIFEST_FORMAT_KIND,
    schemaVersion: BULK_MANIFEST_SCHEMA_VERSION,
    exportedAt: new Date().toISOString(),
    sanitized,
    manifest: payload,
    checkpoint: sanitized ? undefined : checkpoint,
  };
}

export function exportManifestJson(manifest: BulkManifest, checkpoint?: BulkRunCheckpoint): string {
  return JSON.stringify(exportManifestEnvelope(manifest, checkpoint, true), null, 2);
}

export function importManifestEnvelope(raw: unknown): {
  ok: true;
  manifest: BulkManifest;
  checkpoint?: BulkRunCheckpoint;
} | { ok: false; message: string } {
  if (!raw || typeof raw !== 'object') {
    return { ok: false, message: 'Import envelope must be an object.' };
  }
  const envelope = raw as Partial<BulkExportEnvelope>;
  if (envelope.formatKind !== BULK_MANIFEST_FORMAT_KIND) {
    return { ok: false, message: 'Unsupported bulk manifest format.' };
  }
  if (envelope.schemaVersion !== BULK_MANIFEST_SCHEMA_VERSION) {
    return { ok: false, message: `Unsupported schema version: ${envelope.schemaVersion}` };
  }
  if (!envelope.manifest) {
    return { ok: false, message: 'Manifest payload missing.' };
  }
  if (!verifyManifestChecksum(envelope.manifest)) {
    return { ok: false, message: 'Manifest checksum mismatch.' };
  }
  const validation = validateManifestOperations(envelope.manifest.operations, envelope.manifest.dependencyEdges);
  if (!validation.valid) {
    return { ok: false, message: validation.issues.find((i) => i.severity === 'error')?.message ?? 'Validation failed.' };
  }
  return { ok: true, manifest: envelope.manifest, checkpoint: envelope.checkpoint };
}

export function downloadBulkExport(content: string, filename: string): void {
  const blob = new Blob([content], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
}

export async function readBulkImportFile(file: File): Promise<
  | { ok: true; manifest: BulkManifest; checkpoint?: BulkRunCheckpoint }
  | { ok: false; message: string }
> {
  try {
    const text = await file.text();
    const parsed = JSON.parse(text) as unknown;
    return importManifestEnvelope(parsed);
  } catch (error) {
    return { ok: false, message: (error as Error).message };
  }
}

export function exportReconciliationCsv(
  checkpoint: BulkRunCheckpoint,
  manifest: BulkManifest
): string {
  const header = 'operationId,family,status,attempts,txHash,lastError\n';
  const ops = new Map(manifest.operations.map((op) => [op.id, op]));
  const rows = checkpoint.operationStates.map((state) => {
    const op = ops.get(state.operationId);
    return [
      state.operationId,
      op?.family ?? '',
      state.status,
      String(state.attempts.length),
      state.txHash ?? '',
      state.lastError ?? '',
    ]
      .map((cell) => `"${String(cell).replace(/"/g, '""')}"`)
      .join(',');
  });
  return header + rows.join('\n');
}
