/**
 * Retry classification and backoff for bulk operation attempts.
 */

import type { BulkOperationAttempt, BulkOperationSpec } from '../../types/bulkOperationsPlanner';

export interface RetryDecision {
  shouldRetry: boolean;
  delayMs: number;
  reason: string;
}

const RETRYABLE_PATTERNS = [
  /timeout/i,
  /network/i,
  /503/,
  /429/,
  /rate limit/i,
  /temporarily unavailable/i,
  /connection reset/i,
];

const NON_RETRYABLE_PATTERNS = [
  /op_underfunded/i,
  /op_no_trust/i,
  /op_line_full/i,
  /bad auth/i,
  /invalid/i,
  /malformed/i,
  /tx_insufficient_fee/i,
  /tx_bad_seq/i,
];

export function classifyRetryability(error: string): boolean {
  if (NON_RETRYABLE_PATTERNS.some((pattern) => pattern.test(error))) return false;
  if (RETRYABLE_PATTERNS.some((pattern) => pattern.test(error))) return true;
  return false;
}

export function computeBackoffMs(attemptNumber: number, baseMs = 1000, maxMs = 30_000): number {
  const exponential = baseMs * 2 ** Math.max(0, attemptNumber - 1);
  const jitter = Math.floor(Math.random() * 250);
  return Math.min(exponential + jitter, maxMs);
}

export function evaluateRetry(
  operation: BulkOperationSpec,
  attempt: BulkOperationAttempt,
  error: string
): RetryDecision {
  const retryable = classifyRetryability(error);
  const attemptsRemaining = operation.maxRetries - attempt.attemptNumber;

  if (!retryable || attemptsRemaining <= 0) {
    return {
      shouldRetry: false,
      delayMs: 0,
      reason: retryable ? 'Retry limit exhausted.' : 'Error is not retryable.',
    };
  }

  return {
    shouldRetry: true,
    delayMs: computeBackoffMs(attempt.attemptNumber),
    reason: 'Retryable error detected.',
  };
}

export function isStaleSequenceError(error: string): boolean {
  return /tx_bad_seq|sequence/i.test(error);
}

export function isDuplicateSubmission(error: string, existingHash?: string): boolean {
  if (!existingHash) return false;
  return /already exists|duplicate|tx_duplicate/i.test(error);
}

export function shouldSkipAfterDependencyFailure(blockedBy: string[]): boolean {
  return blockedBy.length > 0;
}

export async function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  if (ms <= 0) return;
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(resolve, ms);
    if (signal) {
      signal.addEventListener(
        'abort',
        () => {
          clearTimeout(timer);
          reject(new DOMException('Sleep aborted', 'AbortError'));
        },
        { once: true }
      );
    }
  });
}
