/**
 * Resumable bulk operations planner domain types.
 * Supports dependency-aware execution with checkpointed signing and submission.
 */

export const BULK_MANIFEST_SCHEMA_VERSION = 1 as const;
export const BULK_MANIFEST_FORMAT_KIND = 'stellar-dev-dashboard/bulk-manifest' as const;
export const BULK_RUN_SCHEMA_VERSION = 1 as const;

export type BulkOperationFamily =
  | 'payment'
  | 'changeTrust'
  | 'setOptions'
  | 'sponsorship'
  | 'contractInvoke'
  | 'accountMerge'
  | 'createAccount';

export type BulkOperationStatus =
  | 'draft'
  | 'validated'
  | 'planned'
  | 'awaiting_approval'
  | 'signing'
  | 'submitting'
  | 'completed'
  | 'failed'
  | 'skipped'
  | 'cancelled'
  | 'paused';

export type BulkRunStatus =
  | 'idle'
  | 'planning'
  | 'running'
  | 'paused'
  | 'completed'
  | 'failed'
  | 'cancelled';

export type BulkRowValidationSeverity = 'error' | 'warning' | 'info';

export interface BulkOperationReference {
  id: string;
  label?: string;
}

export interface BulkDependencyEdge {
  fromId: string;
  toId: string;
  reason?: string;
}

export interface BulkPaymentParams {
  destination: string;
  amount: string;
  assetType: 'native' | 'credit_alphanum4' | 'credit_alphanum12';
  assetCode?: string;
  assetIssuer?: string;
  memo?: string;
}

export interface BulkTrustlineParams {
  assetCode: string;
  assetIssuer: string;
  limit?: string;
  remove?: boolean;
}

export interface BulkSetOptionsParams {
  setFlags?: number;
  clearFlags?: number;
  masterWeight?: number;
  lowThreshold?: number;
  medThreshold?: number;
  highThreshold?: number;
  homeDomain?: string;
  signer?: { key: string; weight: number };
}

export interface BulkSponsorshipParams {
  sponsoredId: string;
  operation: 'begin' | 'end' | 'revoke';
}

export interface BulkContractInvokeParams {
  contractId: string;
  functionName: string;
  args: unknown[];
  resourceFee?: string;
}

export interface BulkCreateAccountParams {
  destination: string;
  startingBalance: string;
}

export interface BulkOperationSpec {
  id: string;
  family: BulkOperationFamily;
  sourceAccount: string;
  params:
    | BulkPaymentParams
    | BulkTrustlineParams
    | BulkSetOptionsParams
    | BulkSponsorshipParams
    | BulkContractInvokeParams
    | BulkCreateAccountParams;
  metadata: {
    rowIndex: number;
    externalRef?: string;
    tags?: string[];
    notes?: string;
    idempotencyKey?: string;
  };
  dependencies: string[];
  maxRetries: number;
  timeoutMs: number;
}

export interface BulkRowValidationIssue {
  rowIndex: number;
  operationId?: string;
  field?: string;
  message: string;
  severity: BulkRowValidationSeverity;
  repairHint?: string;
}

export interface BulkValidationReport {
  valid: boolean;
  issues: BulkRowValidationIssue[];
  duplicateIds: string[];
  missingDependencies: Array<{ operationId: string; missingId: string }>;
  cyclicDependencies: string[][];
}

export interface BulkTransactionPack {
  packId: string;
  sourceAccount: string;
  operationIds: string[];
  estimatedFee: string;
  sequence: number;
  maxOperations: number;
}

export interface BulkExecutionPlan {
  planId: string;
  manifestId: string;
  schemaVersion: typeof BULK_MANIFEST_SCHEMA_VERSION;
  createdAt: string;
  packs: BulkTransactionPack[];
  topologicalOrder: string[];
  concurrencyByAccount: Record<string, number>;
  estimatedTotalFee: string;
  checksum: string;
}

export interface BulkManifest {
  formatKind: typeof BULK_MANIFEST_FORMAT_KIND;
  schemaVersion: typeof BULK_MANIFEST_SCHEMA_VERSION;
  manifestId: string;
  label: string;
  network: string;
  createdAt: string;
  updatedAt: string;
  operations: BulkOperationSpec[];
  dependencyEdges: BulkDependencyEdge[];
  defaults: {
    maxRetries: number;
    timeoutMs: number;
    concurrency: number;
    maxOperationsPerTx: number;
  };
  checksum: string;
}

export interface BulkOperationAttempt {
  attemptNumber: number;
  startedAt: string;
  completedAt?: string;
  status: BulkOperationStatus;
  error?: string;
  txHash?: string;
  ledger?: number;
  feeCharged?: string;
  retryable: boolean;
}

export interface BulkOperationState {
  operationId: string;
  status: BulkOperationStatus;
  attempts: BulkOperationAttempt[];
  signedXdr?: string;
  txHash?: string;
  lastError?: string;
  blockedBy?: string[];
  updatedAt: number;
}

export interface BulkRunCheckpoint {
  runId: string;
  manifestId: string;
  planId: string;
  status: BulkRunStatus;
  operationStates: BulkOperationState[];
  currentPackIndex: number;
  pausedAt?: string;
  leaseUntil?: number;
  lastSequenceByAccount: Record<string, number>;
  updatedAt: number;
}

export interface BulkRunReceipt {
  runId: string;
  manifestId: string;
  completedAt: string;
  successful: number;
  failed: number;
  skipped: number;
  totalFee: string;
  transactionHashes: string[];
}

export interface BulkImportMapping {
  family: BulkOperationFamily;
  columns: Record<string, string>;
}

export interface BulkCsvImportOptions {
  mapping: BulkImportMapping;
  hasHeader: boolean;
  delimiter?: string;
  decimalSeparator?: '.' | ',';
}

export interface BulkImportPreview {
  rows: number;
  operations: BulkOperationSpec[];
  validation: BulkValidationReport;
  duplicates: string[];
}

export interface BulkPlannerPreferences {
  concurrency: number;
  maxOperationsPerTx: number;
  simulateBeforeExecute: boolean;
  requireApproval: boolean;
  autoRetry: boolean;
}

export interface BulkReconciliationItem {
  operationId: string;
  expectedStatus: BulkOperationStatus;
  actualStatus: BulkOperationStatus;
  txHash?: string;
  discrepancy?: string;
}

export interface BulkExportEnvelope {
  formatKind: typeof BULK_MANIFEST_FORMAT_KIND;
  schemaVersion: typeof BULK_MANIFEST_SCHEMA_VERSION;
  exportedAt: string;
  sanitized: boolean;
  manifest: BulkManifest;
  checkpoint?: BulkRunCheckpoint;
}

export interface BulkPlannerError {
  code: string;
  message: string;
  retryable: boolean;
  operationId?: string;
}

export interface BulkProgressEvent {
  phase: 'validate' | 'plan' | 'simulate' | 'sign' | 'submit' | 'reconcile';
  processed: number;
  total: number;
  currentOperationId?: string;
  message: string;
}

export interface BulkIdempotencyRecord {
  idempotencyKey: string;
  operationId: string;
  txHash?: string;
  status: BulkOperationStatus;
  updatedAt: number;
}
