import type { CSSProperties } from 'react';
import type { BulkExecutionPlan, BulkManifest, BulkValidationReport } from '../../types/bulkOperationsPlanner';
import { summarizePlan } from '../../lib/bulkOperationsPlanner/packing';

const panel: CSSProperties = {
  background: 'var(--bg-card)',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-lg)',
  padding: 18,
};

const button: CSSProperties = {
  minHeight: 36,
  padding: '7px 12px',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-md)',
  background: 'var(--bg-elevated)',
  color: 'var(--text-secondary)',
  cursor: 'pointer',
  fontSize: 11,
};

interface Props {
  manifest: BulkManifest | null;
  plan: BulkExecutionPlan | null;
  validation: BulkValidationReport | null;
  approved: boolean;
  onDryRun: () => void;
  onApprove: () => void;
}

export default function BulkPlanPanel({ manifest, plan, validation, approved, onDryRun, onApprove }: Props) {
  return (
    <div style={{ display: 'grid', gap: 16 }}>
      <div style={panel}>
        <h3 style={{ margin: '0 0 12px', fontSize: 14 }}>Execution plan</h3>
        {manifest ? (
          <p style={{ fontSize: 12, color: 'var(--text-muted)' }}>
            {manifest.label} · {manifest.operations.length} operations · checksum {manifest.checksum}
          </p>
        ) : (
          <p style={{ fontSize: 12, color: 'var(--text-muted)' }}>Select a manifest to plan.</p>
        )}
        {plan && (
          <p style={{ fontSize: 12, marginTop: 8 }} role="status">
            {summarizePlan(plan)}
          </p>
        )}
        <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
          <button type="button" style={button} onClick={onDryRun}>
            Dry run
          </button>
          <button type="button" style={button} onClick={onApprove} disabled={approved || !validation?.valid}>
            {approved ? 'Approved' : 'Approve plan'}
          </button>
        </div>
      </div>

      {plan && (
        <div style={panel}>
          <h4 style={{ margin: '0 0 12px', fontSize: 13 }}>Transaction packs</h4>
          <ul style={{ margin: 0, padding: 0, listStyle: 'none', display: 'grid', gap: 8, fontSize: 12 }}>
            {plan.packs.map((pack) => (
              <li key={pack.packId} style={{ padding: 10, border: '1px solid var(--border)', borderRadius: 'var(--radius-md)' }}>
                {pack.packId} · seq {pack.sequence} · {pack.operationIds.length} ops · fee {pack.estimatedFee}
              </li>
            ))}
          </ul>
        </div>
      )}

      {validation?.cyclicDependencies.length ? (
        <div style={{ ...panel, color: 'var(--red)', fontSize: 12 }} role="alert">
          Cyclic dependencies detected: {validation.cyclicDependencies.map((c) => c.join(' → ')).join('; ')}
        </div>
      ) : null}
    </div>
  );
}
