/**
 * Dependency graph with cycle detection and deterministic topological ordering.
 */

import type { BulkDependencyEdge, BulkOperationSpec, BulkValidationReport } from '../../types/bulkOperationsPlanner';

export interface GraphNode {
  id: string;
  dependencies: string[];
  dependents: string[];
  index: number;
}

export function buildDependencyGraph(
  operations: BulkOperationSpec[],
  edges: BulkDependencyEdge[] = []
): Map<string, GraphNode> {
  const graph = new Map<string, GraphNode>();

  operations.forEach((op, index) => {
    graph.set(op.id, {
      id: op.id,
      dependencies: [...op.dependencies],
      dependents: [],
      index,
    });
  });

  for (const edge of edges) {
    const from = graph.get(edge.fromId);
    const to = graph.get(edge.toId);
    if (from && to && !from.dependencies.includes(edge.toId)) {
      from.dependencies.push(edge.toId);
    }
  }

  for (const node of graph.values()) {
    for (const depId of node.dependencies) {
      const dep = graph.get(depId);
      if (dep && !dep.dependents.includes(node.id)) {
        dep.dependents.push(node.id);
      }
    }
  }

  return graph;
}

export function findMissingDependencies(
  operations: BulkOperationSpec[],
  graph: Map<string, GraphNode>
): BulkValidationReport['missingDependencies'] {
  const ids = new Set(operations.map((op) => op.id));
  const missing: BulkValidationReport['missingDependencies'] = [];

  for (const op of operations) {
    for (const depId of op.dependencies) {
      if (!ids.has(depId)) {
        missing.push({ operationId: op.id, missingId: depId });
      }
    }
    const node = graph.get(op.id);
    if (node) {
      for (const depId of node.dependencies) {
        if (!ids.has(depId)) {
          missing.push({ operationId: op.id, missingId: depId });
        }
      }
    }
  }

  return missing;
}

export function findDuplicateIds(operations: BulkOperationSpec[]): string[] {
  const seen = new Set<string>();
  const duplicates = new Set<string>();
  for (const op of operations) {
    if (seen.has(op.id)) duplicates.add(op.id);
    seen.add(op.id);
  }
  return [...duplicates];
}

export function detectCycles(graph: Map<string, GraphNode>): string[][] {
  const cycles: string[][] = [];
  const visiting = new Set<string>();
  const visited = new Set<string>();
  const stack: string[] = [];

  function dfs(nodeId: string): void {
    if (visited.has(nodeId)) return;
    if (visiting.has(nodeId)) {
      const cycleStart = stack.indexOf(nodeId);
      if (cycleStart >= 0) {
        cycles.push([...stack.slice(cycleStart), nodeId]);
      }
      return;
    }

    visiting.add(nodeId);
    stack.push(nodeId);
    const node = graph.get(nodeId);
    if (node) {
      for (const depId of node.dependencies) {
        dfs(depId);
      }
    }
    stack.pop();
    visiting.delete(nodeId);
    visited.add(nodeId);
  }

  for (const nodeId of graph.keys()) {
    dfs(nodeId);
  }

  return cycles;
}

export function topologicalSort(
  operations: BulkOperationSpec[],
  graph: Map<string, GraphNode>
): { order: string[]; hasCycle: boolean; cycle?: string[] } {
  const cycles = detectCycles(graph);
  if (cycles.length > 0) {
    return { order: [], hasCycle: true, cycle: cycles[0] };
  }

  const inDegree = new Map<string, number>();
  for (const op of operations) {
    inDegree.set(op.id, graph.get(op.id)?.dependencies.length ?? op.dependencies.length);
  }

  const queue = operations
    .filter((op) => (inDegree.get(op.id) ?? 0) === 0)
    .sort((a, b) => a.metadata.rowIndex - b.metadata.rowIndex || a.id.localeCompare(b.id))
    .map((op) => op.id);

  const order: string[] = [];

  while (queue.length > 0) {
    const current = queue.shift()!;
    order.push(current);
    const node = graph.get(current);
    if (!node) continue;

    for (const dependentId of node.dependents) {
      const nextDegree = (inDegree.get(dependentId) ?? 1) - 1;
      inDegree.set(dependentId, nextDegree);
      if (nextDegree === 0) {
        queue.push(dependentId);
        queue.sort((a, b) => {
          const aIndex = graph.get(a)?.index ?? 0;
          const bIndex = graph.get(b)?.index ?? 0;
          return aIndex - bIndex || a.localeCompare(b);
        });
      }
    }
  }

  if (order.length !== operations.length) {
    return { order: [], hasCycle: true };
  }

  return { order, hasCycle: false };
}

export function computeReadyOperations(
  order: string[],
  states: Map<string, { status: string; blockedBy?: string[] }>,
  graph: Map<string, GraphNode>
): string[] {
  const ready: string[] = [];

  for (const opId of order) {
    const state = states.get(opId);
    if (state && !['draft', 'validated', 'planned', 'paused'].includes(state.status)) {
      continue;
    }

    const node = graph.get(opId);
    if (!node) continue;

    const blocked = node.dependencies.some((depId) => {
      const depState = states.get(depId);
      return !depState || depState.status !== 'completed';
    });

    if (!blocked) ready.push(opId);
  }

  return ready;
}

export function addSequenceDependencies(
  operations: BulkOperationSpec[],
  startSequences: Record<string, number>
): BulkOperationSpec[] {
  const bySource = new Map<string, BulkOperationSpec[]>();

  for (const op of operations) {
    const list = bySource.get(op.sourceAccount) ?? [];
    list.push(op);
    bySource.set(op.sourceAccount, list);
  }

  const sequenceDeps = new Map<string, string>();

  for (const [source, ops] of bySource.entries()) {
    const sorted = [...ops].sort((a, b) => a.metadata.rowIndex - b.metadata.rowIndex);
    for (let i = 1; i < sorted.length; i += 1) {
      sequenceDeps.set(sorted[i].id, sorted[i - 1].id);
    }
    void startSequences[source];
  }

  return operations.map((op) => {
    const seqDep = sequenceDeps.get(op.id);
    if (!seqDep) return op;
    if (op.dependencies.includes(seqDep)) return op;
    return { ...op, dependencies: [...op.dependencies, seqDep] };
  });
}

export function validateGraph(
  operations: BulkOperationSpec[],
  edges: BulkDependencyEdge[] = []
): BulkValidationReport {
  const duplicateIds = findDuplicateIds(operations);
  const graph = buildDependencyGraph(operations, edges);
  const missingDependencies = findMissingDependencies(operations, graph);
  const cycles = detectCycles(graph);
  const sortResult = topologicalSort(operations, graph);

  const issues: BulkValidationReport['issues'] = [];

  for (const id of duplicateIds) {
    issues.push({
      rowIndex: -1,
      operationId: id,
      message: `Duplicate operation id: ${id}`,
      severity: 'error',
    });
  }

  for (const missing of missingDependencies) {
    issues.push({
      rowIndex: -1,
      operationId: missing.operationId,
      message: `Missing dependency ${missing.missingId}`,
      severity: 'error',
      repairHint: 'Add the referenced operation or remove the dependency edge.',
    });
  }

  for (const cycle of cycles) {
    issues.push({
      rowIndex: -1,
      message: `Cyclic dependency detected: ${cycle.join(' → ')}`,
      severity: 'error',
      repairHint: 'Remove one dependency edge to break the cycle.',
    });
  }

  if (sortResult.hasCycle && cycles.length === 0) {
    issues.push({
      rowIndex: -1,
      message: 'Unable to produce topological order due to cyclic dependencies.',
      severity: 'error',
    });
  }

  return {
    valid: issues.filter((i) => i.severity === 'error').length === 0,
    issues,
    duplicateIds,
    missingDependencies,
    cyclicDependencies: cycles,
  };
}
