import type { CSSProperties } from 'react';
import type { BulkProgressEvent, BulkRunCheckpoint } from '../../types/bulkOperationsPlanner';

const panel: CSSProperties = {
  background: 'var(--bg-card)',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-lg)',
  padding: 18,
};

const button: CSSProperties = {
  minHeight: 36,
  padding: '7px 12px',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-md)',
  background: 'var(--bg-elevated)',
  color: 'var(--text-secondary)',
  cursor: 'pointer',
  fontSize: 11,
};

interface Props {
  executing: boolean;
  progress: BulkProgressEvent | null;
  checkpoint: BulkRunCheckpoint | null;
  approved: boolean;
  requireApproval: boolean;
  onExecute: () => void;
  onPause: () => void;
  onResume: () => void;
  onCancel: () => void;
}

export default function BulkExecutePanel({
  executing,
  progress,
  checkpoint,
  approved,
  requireApproval,
  onExecute,
  onPause,
  onResume,
  onCancel,
}: Props) {
  const completed = checkpoint?.operationStates.filter((s) => s.status === 'completed').length ?? 0;
  const total = checkpoint?.operationStates.length ?? 0;

  return (
    <div style={{ display: 'grid', gap: 16 }}>
      <div style={panel}>
        <h3 style={{ margin: '0 0 12px', fontSize: 14 }}>Execution dashboard</h3>
        {requireApproval && !approved && (
          <p style={{ color: 'var(--amber)', fontSize: 12 }} role="alert">
            Plan approval is required before execution.
          </p>
        )}
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          <button type="button" style={button} onClick={onExecute} disabled={executing || (requireApproval && !approved)}>
            {executing ? 'Executing…' : 'Start / continue'}
          </button>
          <button type="button" style={button} onClick={onPause} disabled={!executing}>
            Pause
          </button>
          <button type="button" style={button} onClick={onResume}>
            Resume
          </button>
          <button type="button" style={button} onClick={onCancel}>
            Cancel
          </button>
        </div>
        {progress && (
          <p style={{ fontSize: 12, marginTop: 12 }} aria-live="polite">
            [{progress.phase}] {progress.message} ({progress.processed}/{progress.total})
          </p>
        )}
      </div>

      <div style={{ ...panel, display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(120px,1fr))', gap: 12 }}>
        <Metric label="Status" value={checkpoint?.status ?? 'idle'} />
        <Metric label="Completed" value={`${completed}/${total}`} />
        <Metric label="Failed" value={String(checkpoint?.operationStates.filter((s) => s.status === 'failed').length ?? 0)} />
        <Metric label="Skipped" value={String(checkpoint?.operationStates.filter((s) => s.status === 'skipped').length ?? 0)} />
      </div>

      {checkpoint && (
        <div style={panel}>
          <h4 style={{ margin: '0 0 12px', fontSize: 13 }}>Per-item diagnostics</h4>
          <ul style={{ margin: 0, padding: 0, listStyle: 'none', display: 'grid', gap: 6, fontSize: 11, maxHeight: 320, overflow: 'auto' }}>
            {checkpoint.operationStates.map((state) => (
              <li key={state.operationId} style={{ padding: 8, border: '1px solid var(--border)', borderRadius: 'var(--radius-md)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span>{state.operationId.slice(0, 18)}…</span>
                  <span>{state.status}</span>
                </div>
                {state.lastError && <div style={{ color: 'var(--red)', marginTop: 4 }}>{state.lastError}</div>}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <div style={{ fontSize: 10, color: 'var(--text-muted)', textTransform: 'uppercase' }}>{label}</div>
      <div style={{ fontSize: 16, fontWeight: 600, marginTop: 4 }}>{value}</div>
    </div>
  );
}
