/**
 * Transaction packing by operation limits, dependencies, and sequence constraints.
 */

import type {
  BulkExecutionPlan,
  BulkManifest,
  BulkOperationSpec,
  BulkTransactionPack,
} from '../../types/bulkOperationsPlanner';
import { BULK_MANIFEST_SCHEMA_VERSION } from '../../types/bulkOperationsPlanner';
import { buildDependencyGraph, topologicalSort, addSequenceDependencies } from './dependencyGraph';
import { stableCanonicalJson } from './canonicalize';

const DEFAULT_MAX_OPS = 100;
const BASE_FEE_STROOPS = 100;

function fnv1a(input: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

export interface PackingOptions {
  maxOperationsPerTx?: number;
  startSequences?: Record<string, number>;
  concurrencyByAccount?: Record<string, number>;
}

export function estimateOperationFee(operationCount: number): string {
  return String(operationCount * BASE_FEE_STROOPS);
}

export function packOperationsForAccount(
  sourceAccount: string,
  operationIds: string[],
  order: string[],
  startSequence: number,
  maxOperationsPerTx: number
): BulkTransactionPack[] {
  const orderedIds = order.filter((id) => operationIds.includes(id));
  const packs: BulkTransactionPack[] = [];
  let sequence = startSequence;

  for (let i = 0; i < orderedIds.length; i += maxOperationsPerTx) {
    const chunk = orderedIds.slice(i, i + maxOperationsPerTx);
    packs.push({
      packId: `pack-${sourceAccount.slice(0, 8)}-${sequence}`,
      sourceAccount,
      operationIds: chunk,
      estimatedFee: estimateOperationFee(chunk.length),
      sequence,
      maxOperations: maxOperationsPerTx,
    });
    sequence += 1;
  }

  return packs;
}

export function buildExecutionPlan(
  manifest: BulkManifest,
  options: PackingOptions = {}
): { ok: true; plan: BulkExecutionPlan } | { ok: false; error: string } {
  const maxOps = options.maxOperationsPerTx ?? manifest.defaults.maxOperationsPerTx ?? DEFAULT_MAX_OPS;
  const startSequences = options.startSequences ?? {};

  const withSequenceDeps = addSequenceDependencies(manifest.operations, startSequences);
  const graph = buildDependencyGraph(withSequenceDeps, manifest.dependencyEdges);
  const sortResult = topologicalSort(withSequenceDeps, graph);

  if (sortResult.hasCycle) {
    return { ok: false, error: `Cannot plan execution: cyclic dependency ${sortResult.cycle?.join(' → ') ?? ''}` };
  }

  const bySource = new Map<string, string[]>();
  for (const op of withSequenceDeps) {
    const list = bySource.get(op.sourceAccount) ?? [];
    list.push(op.id);
    bySource.set(op.sourceAccount, list);
  }

  const packs: BulkTransactionPack[] = [];
  for (const [sourceAccount, opIds] of bySource.entries()) {
    const startSeq = startSequences[sourceAccount] ?? 1;
    packs.push(...packOperationsForAccount(sourceAccount, opIds, sortResult.order, startSeq, maxOps));
  }

  packs.sort((a, b) => a.sequence - b.sequence || a.sourceAccount.localeCompare(b.sourceAccount));

  const estimatedTotalFee = String(packs.reduce((sum, pack) => sum + Number(pack.estimatedFee), 0));

  const concurrencyByAccount: Record<string, number> = {};
  for (const source of bySource.keys()) {
    concurrencyByAccount[source] = options.concurrencyByAccount?.[source] ?? manifest.defaults.concurrency ?? 1;
  }

  const planPayload = {
    manifestId: manifest.manifestId,
    packs,
    topologicalOrder: sortResult.order,
  };

  const plan: BulkExecutionPlan = {
    planId: `plan-${manifest.manifestId.slice(0, 8)}-${Date.now()}`,
    manifestId: manifest.manifestId,
    schemaVersion: BULK_MANIFEST_SCHEMA_VERSION,
    createdAt: new Date().toISOString(),
    packs,
    topologicalOrder: sortResult.order,
    concurrencyByAccount,
    estimatedTotalFee,
    checksum: fnv1a(stableCanonicalJson(planPayload)),
  };

  return { ok: true, plan };
}

export function getNextReadyPack(
  plan: BulkExecutionPlan,
  completedPackIds: Set<string>,
  blockedAccounts: Set<string>
): BulkTransactionPack | null {
  for (const pack of plan.packs) {
    if (completedPackIds.has(pack.packId)) continue;
    if (blockedAccounts.has(pack.sourceAccount)) continue;
    return pack;
  }
  return null;
}

export function summarizePlan(plan: BulkExecutionPlan): string {
  return `${plan.packs.length} transaction pack(s), ${plan.topologicalOrder.length} operations, estimated fee ${plan.estimatedTotalFee} stroops`;
}

export function findPackForOperation(plan: BulkExecutionPlan, operationId: string): BulkTransactionPack | undefined {
  return plan.packs.find((pack) => pack.operationIds.includes(operationId));
}

export function validatePackReadiness(
  pack: BulkTransactionPack,
  operationStates: Map<string, { status: string }>,
  graph: ReturnType<typeof buildDependencyGraph>
): { ready: boolean; blockedBy: string[] } {
  const blockedBy: string[] = [];

  for (const opId of pack.operationIds) {
    const node = graph.get(opId);
    if (!node) continue;
    for (const depId of node.dependencies) {
      const depState = operationStates.get(depId);
      if (!depState || depState.status !== 'completed') {
        blockedBy.push(depId);
      }
    }
  }

  return { ready: blockedBy.length === 0, blockedBy };
}

export function splitOperationsByFamily(operations: BulkOperationSpec[]): Record<string, BulkOperationSpec[]> {
  const groups: Record<string, BulkOperationSpec[]> = {};
  for (const op of operations) {
    groups[op.family] = groups[op.family] ?? [];
    groups[op.family].push(op);
  }
  return groups;
}
