/**
 * CSV and JSON import with schema mapping, previews, and duplicate detection.
 */

import type {
  BulkCsvImportOptions,
  BulkImportPreview,
  BulkManifest,
  BulkOperationSpec,
} from '../../types/bulkOperationsPlanner';
import { buildManifest } from './planner';
import { buildOperationSpec, detectDuplicateRows, normalizeDecimal, validateManifestOperations } from './validation';

function parseCsvLine(line: string, delimiter: string): string[] {
  const cells: string[] = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i += 1) {
    const char = line[i];
    if (char === '"') {
      inQuotes = !inQuotes;
      continue;
    }
    if (char === delimiter && !inQuotes) {
      cells.push(current.trim());
      current = '';
      continue;
    }
    current += char;
  }
  cells.push(current.trim());
  return cells;
}

export function parseCsv(text: string, delimiter = ',', hasHeader = true): { headers: string[]; rows: string[][] } {
  const lines = text
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);

  if (lines.length === 0) return { headers: [], rows: [] };

  const headers = hasHeader ? parseCsvLine(lines[0], delimiter) : [];
  const dataLines = hasHeader ? lines.slice(1) : lines;
  const rows = dataLines.map((line) => parseCsvLine(line, delimiter));

  if (!hasHeader && rows.length > 0) {
    return {
      headers: rows[0].map((_, index) => `column_${index}`),
      rows: rows.slice(1),
    };
  }

  return { headers, rows };
}

export function mapRowToOperation(
  headers: string[],
  row: string[],
  mapping: BulkCsvImportOptions['mapping'],
  rowIndex: number,
  sourceAccount: string,
  decimalSeparator: '.' | ',' = '.'
): BulkOperationSpec | null {
  const record: Record<string, string> = {};
  headers.forEach((header, index) => {
    record[header] = row[index] ?? '';
  });

  const get = (field: string) => record[mapping.columns[field] ?? field] ?? '';

  switch (mapping.family) {
    case 'payment':
      return buildOperationSpec({
        family: 'payment',
        sourceAccount: get('sourceAccount') || sourceAccount,
        rowIndex,
        externalRef: get('externalRef'),
        payload: {
          destination: get('destination'),
          amount: normalizeDecimal(get('amount'), decimalSeparator),
          assetType: (get('assetType') as 'native') || 'native',
          assetCode: get('assetCode') || undefined,
          assetIssuer: get('assetIssuer') || undefined,
          memo: get('memo') || undefined,
        },
      });
    case 'changeTrust':
      return buildOperationSpec({
        family: 'changeTrust',
        sourceAccount: get('sourceAccount') || sourceAccount,
        rowIndex,
        externalRef: get('externalRef'),
        payload: {
          assetCode: get('assetCode'),
          assetIssuer: get('assetIssuer'),
          limit: get('limit') || undefined,
          remove: get('remove') === 'true',
        },
      });
    case 'createAccount':
      return buildOperationSpec({
        family: 'createAccount',
        sourceAccount: get('sourceAccount') || sourceAccount,
        rowIndex,
        externalRef: get('externalRef'),
        payload: {
          destination: get('destination'),
          startingBalance: normalizeDecimal(get('startingBalance'), decimalSeparator),
        },
      });
    default:
      return null;
  }
}

export function importCsvPreview(
  text: string,
  sourceAccount: string,
  options: BulkCsvImportOptions
): BulkImportPreview {
  const delimiter = options.delimiter ?? ',';
  const { headers, rows } = parseCsv(text, delimiter, options.hasHeader);
  const operations: BulkOperationSpec[] = [];

  rows.forEach((row, index) => {
    const op = mapRowToOperation(headers, row, options.mapping, index, sourceAccount, options.decimalSeparator);
    if (op) operations.push(op);
  });

  const validation = validateManifestOperations(operations);
  const duplicates = detectDuplicateRows(operations);

  if (duplicates.length > 0) {
    validation.issues.push({
      rowIndex: -1,
      message: `Detected ${duplicates.length} duplicate row(s).`,
      severity: 'warning',
      repairHint: 'Remove or deduplicate rows before execution.',
    });
  }

  return { rows: rows.length, operations, validation, duplicates };
}

export function importCsvManifest(
  text: string,
  label: string,
  network: string,
  sourceAccount: string,
  options: BulkCsvImportOptions
): BulkManifest {
  const preview = importCsvPreview(text, sourceAccount, options);
  return buildManifest({
    label,
    network,
    operations: preview.operations,
  });
}

export function importJsonManifest(raw: unknown, label: string, network: string): BulkManifest {
  if (!raw || typeof raw !== 'object') {
    throw new Error('JSON manifest must be an object.');
  }
  const candidate = raw as { operations?: BulkOperationSpec[]; dependencyEdges?: BulkManifest['dependencyEdges'] };
  if (!Array.isArray(candidate.operations)) {
    throw new Error('JSON manifest must include an operations array.');
  }
  return buildManifest({
    label,
    network,
    operations: candidate.operations,
    dependencyEdges: candidate.dependencyEdges,
  });
}

export function exportCsvTemplate(family: BulkCsvImportOptions['mapping']['family']): string {
  switch (family) {
    case 'payment':
      return 'externalRef,destination,amount,assetType,assetCode,assetIssuer,memo\npay-1,G...,10.0000000,native,,,\n';
    case 'changeTrust':
      return 'externalRef,assetCode,assetIssuer,limit,remove\ntl-1,USDC,G...,1000000.0000000,false\n';
    case 'createAccount':
      return 'externalRef,destination,startingBalance\nca-1,G...,2.0000000\n';
    default:
      return 'externalRef,sourceAccount,payload\n';
  }
}
