/**
 * Validation, decimal safety, and address validation for bulk operations.
 */

import type {
  BulkDependencyEdge,
  BulkOperationFamily,
  BulkOperationSpec,
  BulkPaymentParams,
  BulkRowValidationIssue,
  BulkValidationReport,
} from '../../types/bulkOperationsPlanner';
import { validateGraph } from './dependencyGraph';

const STELLAR_PUBLIC_KEY = /^G[A-Z2-7]{54,55}$/;
const STELLAR_CONTRACT = /^C[A-Z2-7]{54,55}$/;
const DECIMAL_PATTERN = /^\d+(\.\d{1,7})?$/;

export function isValidStellarAddress(value: string): boolean {
  return STELLAR_PUBLIC_KEY.test(value.trim());
}

export function isValidContractId(value: string): boolean {
  return STELLAR_CONTRACT.test(value.trim());
}

export function normalizeDecimal(value: string, separator: '.' | ',' = '.'): string {
  const trimmed = value.trim();
  if (separator === ',') {
    return trimmed.replace(/\./g, '').replace(',', '.');
  }
  return trimmed.replace(/,/g, '');
}

export function validateDecimal(value: string, field: string, rowIndex: number): BulkRowValidationIssue | null {
  const normalized = normalizeDecimal(value);
  if (!DECIMAL_PATTERN.test(normalized)) {
    return {
      rowIndex,
      field,
      message: `Invalid decimal amount: ${value}`,
      severity: 'error',
      repairHint: 'Use up to 7 decimal places.',
    };
  }
  if (Number(normalized) <= 0) {
    return {
      rowIndex,
      field,
      message: 'Amount must be greater than zero.',
      severity: 'error',
    };
  }
  return null;
}

export function validateOperationSpec(op: BulkOperationSpec): BulkRowValidationIssue[] {
  const issues: BulkRowValidationIssue[] = [];
  const rowIndex = op.metadata.rowIndex;

  if (!op.id?.trim()) {
    issues.push({ rowIndex, message: 'Operation id is required.', severity: 'error' });
  }

  if (!isValidStellarAddress(op.sourceAccount)) {
    issues.push({
      rowIndex,
      operationId: op.id,
      field: 'sourceAccount',
      message: 'Invalid source account.',
      severity: 'error',
    });
  }

  switch (op.family) {
    case 'payment': {
      const params = op.params as { destination: string; amount: string };
      if (!isValidStellarAddress(params.destination)) {
        issues.push({
          rowIndex,
          operationId: op.id,
          field: 'destination',
          message: 'Invalid payment destination.',
          severity: 'error',
        });
      }
      const decimalIssue = validateDecimal(params.amount, 'amount', rowIndex);
      if (decimalIssue) issues.push({ ...decimalIssue, operationId: op.id });
      break;
    }
    case 'changeTrust': {
      const params = op.params as { assetCode: string; assetIssuer: string };
      if (!params.assetCode?.trim()) {
        issues.push({ rowIndex, operationId: op.id, field: 'assetCode', message: 'Asset code required.', severity: 'error' });
      }
      if (!isValidStellarAddress(params.assetIssuer)) {
        issues.push({ rowIndex, operationId: op.id, field: 'assetIssuer', message: 'Invalid issuer.', severity: 'error' });
      }
      break;
    }
    case 'contractInvoke': {
      const params = op.params as { contractId: string; functionName: string };
      if (!isValidContractId(params.contractId)) {
        issues.push({ rowIndex, operationId: op.id, field: 'contractId', message: 'Invalid contract id.', severity: 'error' });
      }
      if (!params.functionName?.trim()) {
        issues.push({ rowIndex, operationId: op.id, field: 'functionName', message: 'Function name required.', severity: 'error' });
      }
      break;
    }
    case 'createAccount': {
      const params = op.params as { destination: string; startingBalance: string };
      if (!isValidStellarAddress(params.destination)) {
        issues.push({ rowIndex, operationId: op.id, field: 'destination', message: 'Invalid destination.', severity: 'error' });
      }
      const decimalIssue = validateDecimal(params.startingBalance, 'startingBalance', rowIndex);
      if (decimalIssue) issues.push({ ...decimalIssue, operationId: op.id });
      break;
    }
    default:
      break;
  }

  return issues;
}

export function validateAllOperations(operations: BulkOperationSpec[]): BulkRowValidationIssue[] {
  return operations.flatMap(validateOperationSpec);
}

export function validateManifestOperations(
  operations: BulkOperationSpec[],
  edges: BulkDependencyEdge[] = []
): BulkValidationReport {
  const rowIssues = validateAllOperations(operations);
  const graphReport = validateGraph(operations, edges);
  return {
    ...graphReport,
    issues: [...rowIssues, ...graphReport.issues],
    valid: graphReport.valid && rowIssues.every((i) => i.severity !== 'error'),
  };
}

export function stableOperationId(parts: Array<string | number>): string {
  const payload = parts.join(':');
  let hash = 0x811c9dc5;
  for (let i = 0; i < payload.length; i += 1) {
    hash ^= payload.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return `bulk-op-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

export function buildOperationSpec(params: {
  family: BulkOperationFamily;
  sourceAccount: string;
  rowIndex: number;
  payload: BulkOperationSpec['params'];
  dependencies?: string[];
  externalRef?: string;
}): BulkOperationSpec {
  const id = stableOperationId([params.family, params.sourceAccount, params.rowIndex, params.externalRef ?? '']);
  return {
    id,
    family: params.family,
    sourceAccount: params.sourceAccount,
    params: params.payload,
    metadata: {
      rowIndex: params.rowIndex,
      externalRef: params.externalRef,
      idempotencyKey: id,
    },
    dependencies: params.dependencies ?? [],
    maxRetries: 3,
    timeoutMs: 30_000,
  };
}

export function detectDuplicateRows(operations: BulkOperationSpec[]): string[] {
  const seen = new Map<string, string>();
  const duplicates: string[] = [];

  for (const op of operations) {
    const fingerprint = stableOperationId([
      op.family,
      op.sourceAccount,
      JSON.stringify(op.params),
      op.metadata.externalRef ?? '',
    ]);
    if (seen.has(fingerprint)) {
      duplicates.push(op.id);
    }
    seen.set(fingerprint, op.id);
  }

  return duplicates;
}

export function repairMissingAssetFields(
  op: BulkOperationSpec
): { operation: BulkOperationSpec; repaired: boolean; message?: string } {
  if (op.family !== 'payment') return { operation: op, repaired: false };
  const params = op.params as BulkPaymentParams;
  if (params.assetType && params.assetType !== 'native') return { operation: op, repaired: false };
  if (!params.assetCode && !params.assetIssuer) {
    return {
      operation: {
        ...op,
        params: { ...params, assetType: 'native' },
      },
      repaired: true,
      message: 'Defaulted asset type to native XLM.',
    };
  }
  return { operation: op, repaired: false };
}
