/**
 * Resumable bulk executor with checkpointing, pause/resume, and idempotency.
 */

import type { NetworkName } from '../stellar';
import { buildTransaction } from '../transactionBuilder';
import type {
  BulkExecutionPlan,
  BulkManifest,
  BulkOperationAttempt,
  BulkOperationSpec,
  BulkOperationState,
  BulkProgressEvent,
  BulkRunCheckpoint,
  BulkRunReceipt,
  BulkRunStatus,
} from '../../types/bulkOperationsPlanner';
import { BULK_RUN_SCHEMA_VERSION } from '../../types/bulkOperationsPlanner';
import { buildDependencyGraph, computeReadyOperations } from './dependencyGraph';
import { evaluateRetry, isDuplicateSubmission, isStaleSequenceError, sleep } from './retryPolicy';

export interface SubmitResult {
  hash: string;
  ledger: number;
  successful: boolean;
  feeCharged?: string;
}

export interface BulkExecutorDependencies {
  submitTransaction: (
    _xdr: string,
    _network: NetworkName,
    _signal?: AbortSignal
  ) => Promise<SubmitResult>;
  signTransaction: (
    _xdr: string,
    _network: NetworkName,
    _signal?: AbortSignal
  ) => Promise<string>;
  simulateTransaction?: (
    _xdr: string,
    _network: NetworkName,
    _signal?: AbortSignal
  ) => Promise<{ successful: boolean; error?: string }>;
  buildOperationXdr?: (_op: BulkOperationSpec, _network: NetworkName) => Promise<string>;
  now?: () => Date;
  idFactory?: () => string;
}

function createId(factory?: () => string): string {
  if (factory) return factory();
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return `run-${Date.now()}`;
}

function initialOperationStates(operations: BulkOperationSpec[]): BulkOperationState[] {
  return operations.map((op) => ({
    operationId: op.id,
    status: 'planned',
    attempts: [],
    updatedAt: Date.now(),
  }));
}

export class BulkOperationExecutor {
  private deps: BulkExecutorDependencies;

  constructor(deps: BulkExecutorDependencies) {
    this.deps = deps;
  }

  createCheckpoint(
    runId: string,
    manifest: BulkManifest,
    plan: BulkExecutionPlan,
    operationStates: BulkOperationState[] = initialOperationStates(manifest.operations),
    status: BulkRunStatus = 'idle'
  ): BulkRunCheckpoint {
    return {
      runId,
      manifestId: manifest.manifestId,
      planId: plan.planId,
      status,
      operationStates,
      currentPackIndex: 0,
      lastSequenceByAccount: {},
      updatedAt: Date.now(),
    };
  }

  async execute(
    manifest: BulkManifest,
    plan: BulkExecutionPlan,
    checkpoint: BulkRunCheckpoint,
    network: NetworkName,
    options: {
      simulateFirst?: boolean;
      signal?: AbortSignal;
      onProgress?: (event: BulkProgressEvent) => void;
    } = {}
  ): Promise<{ checkpoint: BulkRunCheckpoint; receipt: BulkRunReceipt | null }> {
    const now = this.deps.now?.() ?? new Date();
    let working = { ...checkpoint, status: 'running' as BulkRunStatus };
    const graph = buildDependencyGraph(manifest.operations, manifest.dependencyEdges);
    const operationsById = new Map(manifest.operations.map((op) => [op.id, op]));

    const stateLookup = () => new Map(working.operationStates.map((s) => [s.operationId, s]));
    let states = stateLookup();
    const total = plan.topologicalOrder.length;
    let processed = 0;

    const emit = (event: Omit<BulkProgressEvent, 'processed' | 'total'>) => {
      options.onProgress?.({ ...event, processed, total });
    };

    emit({ phase: 'plan', message: 'Starting bulk execution…' });

    for (const opId of plan.topologicalOrder) {
      if (options.signal?.aborted || working.status === 'paused' || working.status === 'cancelled') {
        break;
      }

      const op = operationsById.get(opId);
      const state = states.get(opId);
      if (!op || !state) continue;
      if (state.status === 'completed' || state.status === 'skipped' || state.status === 'cancelled') {
        processed += 1;
        continue;
      }

      const node = graph.get(opId);
      if (node) {
        const blocked = node.dependencies.some((depId) => {
          const depState = states.get(depId);
          return !depState || depState.status !== 'completed';
        });
        if (blocked) {
          const blockedBy = node.dependencies.filter((depId) => {
            const depState = states.get(depId);
            return !depState || depState.status !== 'completed';
          });
          working = this.updateOperationState(working, opId, {
            status: 'skipped',
            lastError: `Blocked by dependencies: ${blockedBy.join(', ')}`,
            blockedBy,
          });
          states = stateLookup();
          processed += 1;
          continue;
        }
      }

      emit({ phase: 'simulate', message: `Processing ${op.family} operation`, currentOperationId: opId });

      try {
        const xdr = await this.buildOperationXdr(op, network);
        if (options.simulateFirst && this.deps.simulateTransaction) {
          const simulation = await this.deps.simulateTransaction(xdr, network, options.signal);
          if (!simulation.successful) {
            throw new Error(simulation.error ?? 'Simulation failed.');
          }
        }

        emit({ phase: 'sign', message: 'Signing transaction', currentOperationId: opId });
        const signedXdr = await this.deps.signTransaction(xdr, network, options.signal);

        emit({ phase: 'submit', message: 'Submitting transaction', currentOperationId: opId });
        const attemptNumber = state.attempts.length + 1;
        const attempt: BulkOperationAttempt = {
          attemptNumber,
          startedAt: now.toISOString(),
          status: 'submitting',
          retryable: false,
        };

        const result = await this.deps.submitTransaction(signedXdr, network, options.signal);
        attempt.completedAt = (this.deps.now?.() ?? new Date()).toISOString();
        attempt.status = result.successful ? 'completed' : 'failed';
        attempt.txHash = result.hash;
        attempt.ledger = result.ledger;
        attempt.feeCharged = result.feeCharged;

        working = this.updateOperationState(working, opId, {
          status: result.successful ? 'completed' : 'failed',
          signedXdr,
          txHash: result.hash,
          attempts: [...state.attempts, attempt],
        });
      } catch (error) {
        const message = (error as Error).message;
        const attemptNumber = state.attempts.length + 1;
        const attempt: BulkOperationAttempt = {
          attemptNumber,
          startedAt: now.toISOString(),
          completedAt: (this.deps.now?.() ?? new Date()).toISOString(),
          status: 'failed',
          error: message,
          retryable: false,
        };

        if (isDuplicateSubmission(message, state.txHash)) {
          working = this.updateOperationState(working, opId, {
            status: 'completed',
            attempts: [...state.attempts, attempt],
          });
        } else {
          const decision = evaluateRetry(op, attempt, message);
          attempt.retryable = decision.shouldRetry;

          if (decision.shouldRetry) {
            working = this.updateOperationState(working, opId, {
              status: 'paused',
              lastError: message,
              attempts: [...state.attempts, attempt],
            });
            await sleep(decision.delayMs, options.signal);
            continue;
          }

          if (isStaleSequenceError(message)) {
            working = this.updateOperationState(working, opId, {
              status: 'failed',
              lastError: 'Stale sequence — refresh account sequence before retry.',
              attempts: [...state.attempts, attempt],
            });
          } else {
            working = this.updateOperationState(working, opId, {
              status: 'failed',
              lastError: message,
              attempts: [...state.attempts, attempt],
            });
          }
        }
      }

      states = stateLookup();
      processed += 1;
      working = { ...working, updatedAt: Date.now() };
    }

    const successful = working.operationStates.filter((s) => s.status === 'completed').length;
    const failed = working.operationStates.filter((s) => s.status === 'failed').length;
    const skipped = working.operationStates.filter((s) => s.status === 'skipped').length;
    const allDone = successful + failed + skipped === total;

    working.status = allDone ? (failed > 0 ? 'failed' : 'completed') : working.status;

    const receipt: BulkRunReceipt | null = allDone
      ? {
          runId: working.runId,
          manifestId: manifest.manifestId,
          completedAt: (this.deps.now?.() ?? new Date()).toISOString(),
          successful,
          failed,
          skipped,
          totalFee: String(
            working.operationStates.reduce(
              (sum, s) => sum + Number(s.attempts[s.attempts.length - 1]?.feeCharged ?? 0),
              0
            )
          ),
          transactionHashes: working.operationStates
            .map((s) => s.txHash)
            .filter((hash): hash is string => Boolean(hash)),
        }
      : null;

    emit({ phase: 'reconcile', message: `Execution ${working.status}` });

    return { checkpoint: working, receipt };
  }

  pause(checkpoint: BulkRunCheckpoint): BulkRunCheckpoint {
    return {
      ...checkpoint,
      status: 'paused',
      pausedAt: new Date().toISOString(),
      updatedAt: Date.now(),
    };
  }

  resume(checkpoint: BulkRunCheckpoint): BulkRunCheckpoint {
    return {
      ...checkpoint,
      status: 'running',
      pausedAt: undefined,
      updatedAt: Date.now(),
    };
  }

  cancel(checkpoint: BulkRunCheckpoint): BulkRunCheckpoint {
    return {
      ...checkpoint,
      status: 'cancelled',
      operationStates: checkpoint.operationStates.map((state) =>
        state.status === 'completed' ? state : { ...state, status: 'cancelled', updatedAt: Date.now() }
      ),
      updatedAt: Date.now(),
    };
  }

  getReadyOperations(checkpoint: BulkRunCheckpoint, manifest: BulkManifest, plan: BulkExecutionPlan): string[] {
    const graph = buildDependencyGraph(manifest.operations, manifest.dependencyEdges);
    const states = new Map(checkpoint.operationStates.map((s) => [s.operationId, s]));
    return computeReadyOperations(plan.topologicalOrder, states, graph);
  }

  private updateOperationState(
    checkpoint: BulkRunCheckpoint,
    operationId: string,
    patch: Partial<BulkOperationState>
  ): BulkRunCheckpoint {
    return {
      ...checkpoint,
      operationStates: checkpoint.operationStates.map((state) =>
        state.operationId === operationId ? { ...state, ...patch, updatedAt: Date.now() } : state
      ),
      updatedAt: Date.now(),
    };
  }

  private async buildOperationXdr(op: BulkOperationSpec, network: NetworkName): Promise<string> {
    if (this.deps.buildOperationXdr) {
      return this.deps.buildOperationXdr(op, network);
    }
    const tx = await buildTransaction({
      sourceAccount: op.sourceAccount,
      network,
      operations: [this.toBuilderOperation(op)],
    });
    return tx.toXDR();
  }

  private toBuilderOperation(op: BulkOperationSpec): { type: string; params: Record<string, unknown> } {
    switch (op.family) {
      case 'payment':
        return { type: 'payment', params: op.params as Record<string, unknown> };
      case 'changeTrust':
        return { type: 'changeTrust', params: op.params as Record<string, unknown> };
      case 'setOptions':
        return { type: 'setOptions', params: op.params as Record<string, unknown> };
      case 'createAccount':
        return { type: 'createAccount', params: op.params as Record<string, unknown> };
      default:
        return { type: op.family, params: op.params as Record<string, unknown> };
    }
  }
}

export function createSimulatedExecutor(): BulkOperationExecutor {
  let seq = 1000;
  return new BulkOperationExecutor({
    buildOperationXdr: async (op) => `SIMULATED-XDR-${op.id}`,
    signTransaction: async (xdr) => xdr,
    submitTransaction: async () => {
      seq += 1;
      return { hash: `sim-tx-${seq}`, ledger: seq, successful: true, feeCharged: '100' };
    },
    simulateTransaction: async () => ({ successful: true }),
    now: () => new Date('2024-01-01T00:00:00Z'),
    idFactory: () => `sim-run-${seq}`,
  });
}

export const BULK_RUN_VERSION = BULK_RUN_SCHEMA_VERSION;
