import type { CSSProperties } from 'react';
import type { BulkImportPreview, BulkValidationReport } from '../../types/bulkOperationsPlanner';

const panel: CSSProperties = {
  background: 'var(--bg-card)',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-lg)',
  padding: 18,
};

interface Props {
  preview: BulkImportPreview | null;
  validation: BulkValidationReport | null;
}

export default function BulkPreviewPanel({ preview, validation }: Props) {
  if (!preview) {
    return (
      <div style={panel}>
        <p style={{ color: 'var(--text-muted)', fontSize: 12 }}>Import CSV to preview mapped operations.</p>
      </div>
    );
  }

  return (
    <div style={{ display: 'grid', gap: 16 }}>
      <div style={{ ...panel, display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(120px,1fr))', gap: 12 }}>
        <Metric label="Rows" value={String(preview.rows)} />
        <Metric label="Operations" value={String(preview.operations.length)} />
        <Metric label="Duplicates" value={String(preview.duplicates.length)} />
        <Metric label="Valid" value={validation?.valid ? 'Yes' : 'No'} />
      </div>

      <div style={panel}>
        <h3 style={{ margin: '0 0 12px', fontSize: 14 }}>Validation issues</h3>
        {validation?.issues.length ? (
          <ul style={{ margin: 0, paddingLeft: 18, fontSize: 12 }}>
            {validation.issues.map((issue, index) => (
              <li key={`${issue.message}-${index}`} style={{ color: issue.severity === 'error' ? 'var(--red)' : 'var(--amber)' }}>
                {issue.message}
                {issue.repairHint ? ` — ${issue.repairHint}` : ''}
              </li>
            ))}
          </ul>
        ) : (
          <p style={{ color: 'var(--green)', fontSize: 12 }}>No validation issues.</p>
        )}
      </div>

      <div style={panel}>
        <h3 style={{ margin: '0 0 12px', fontSize: 14 }}>Mapped operations</h3>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 11 }}>
          <thead>
            <tr style={{ textAlign: 'left', color: 'var(--text-muted)' }}>
              <th style={{ padding: 6 }}>#</th>
              <th style={{ padding: 6 }}>Family</th>
              <th style={{ padding: 6 }}>Id</th>
              <th style={{ padding: 6 }}>Source</th>
            </tr>
          </thead>
          <tbody>
            {preview.operations.slice(0, 50).map((op) => (
              <tr key={op.id} style={{ borderTop: '1px solid var(--border)' }}>
                <td style={{ padding: 6 }}>{op.metadata.rowIndex}</td>
                <td style={{ padding: 6 }}>{op.family}</td>
                <td style={{ padding: 6, fontFamily: 'monospace' }}>{op.id.slice(0, 16)}…</td>
                <td style={{ padding: 6, fontFamily: 'monospace' }}>{op.sourceAccount.slice(0, 10)}…</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <div style={{ fontSize: 10, color: 'var(--text-muted)', textTransform: 'uppercase' }}>{label}</div>
      <div style={{ fontSize: 16, fontWeight: 600, marginTop: 4 }}>{value}</div>
    </div>
  );
}
