/**
 * Deterministic fixtures for bulk operations planner tests and offline demo.
 */

import type { BulkManifest, BulkOperationSpec } from '../../types/bulkOperationsPlanner';
import { buildManifest } from './planner';
import { buildOperationSpec } from './validation';

export const DEMO_SOURCE = 'GAAZI4TCR3TY5OJHCTJC2A4QSY6CJWJH5IAJTGKIN2ER7LBNVKOCCWN';
export const DEMO_DEST_A = 'GBLOBGCLOGBLOGBCLOGBLOGBCLOGBLOGBCLOGBLOGBCLOGBLOGBCLAA';
export const DEMO_DEST_B = 'GVENDVENDVENDVENDVENDVENDVENDVENDVENDVENDVENDVENDVENAAA';
export const DEMO_ISSUER = 'GISSUERISSUERISSUERISSUERISSUERISSUERISSUERISSUERISSAAA';

export function buildDemoPaymentOperations(count = 5): BulkOperationSpec[] {
  return Array.from({ length: count }, (_, index) =>
    buildOperationSpec({
      family: 'payment',
      sourceAccount: DEMO_SOURCE,
      rowIndex: index,
      externalRef: `pay-${index + 1}`,
      payload: {
        destination: index % 2 === 0 ? DEMO_DEST_A : DEMO_DEST_B,
        amount: `${(index + 1) * 10}.0000000`,
        assetType: 'native',
      },
      dependencies: index > 0 ? [] : [],
    })
  );
}

export function buildDemoManifest(): BulkManifest {
  const operations = buildDemoPaymentOperations(8);
  operations[2].dependencies = [operations[0].id];
  operations[4].dependencies = [operations[2].id];

  return buildManifest({
    label: 'Deterministic bulk payments demo',
    network: 'testnet',
    operations,
    dependencyEdges: [
      { fromId: operations[2].id, toId: operations[0].id, reason: 'Wait for funding confirmation' },
      { fromId: operations[4].id, toId: operations[2].id, reason: 'Sequential vendor payouts' },
    ],
    defaults: { concurrency: 1, maxOperationsPerTx: 50, maxRetries: 3, timeoutMs: 30_000 },
  });
}

export function buildCyclicManifest(): BulkManifest {
  const opA = buildOperationSpec({
    family: 'payment',
    sourceAccount: DEMO_SOURCE,
    rowIndex: 0,
    externalRef: 'a',
    payload: { destination: DEMO_DEST_A, amount: '1.0000000', assetType: 'native' },
    dependencies: [],
  });
  const opB = buildOperationSpec({
    family: 'payment',
    sourceAccount: DEMO_SOURCE,
    rowIndex: 1,
    externalRef: 'b',
    payload: { destination: DEMO_DEST_B, amount: '2.0000000', assetType: 'native' },
    dependencies: [opA.id],
  });
  opA.dependencies = [opB.id];

  return buildManifest({
    label: 'Cyclic dependency demo',
    network: 'testnet',
    operations: [opA, opB],
    dependencyEdges: [
      { fromId: opA.id, toId: opB.id },
      { fromId: opB.id, toId: opA.id },
    ],
  });
}

export const DEMO_CSV_PAYMENTS = `externalRef,destination,amount,assetType
pay-1,${DEMO_DEST_A},10.0000000,native
pay-2,${DEMO_DEST_B},20.0000000,native
pay-3,${DEMO_DEST_A},5.0000000,native
`;

export function buildLargeManifest(rowCount: number): BulkManifest {
  return buildManifest({
    label: `Large bulk manifest (${rowCount})`,
    network: 'testnet',
    operations: buildDemoPaymentOperations(rowCount),
  });
}
