export class BulkPlannerError extends Error {
  code: string;
  retryable: boolean;
  operationId?: string;

  constructor(params: { code: string; message: string; retryable?: boolean; operationId?: string }) {
    super(params.message);
    this.name = 'BulkPlannerError';
    this.code = params.code;
    this.retryable = params.retryable ?? false;
    this.operationId = params.operationId;
  }
}

export function toBulkPlannerError(error: unknown, operationId?: string): BulkPlannerError {
  if (error instanceof BulkPlannerError) return error;
  return new BulkPlannerError({
    code: 'UNKNOWN',
    message: error instanceof Error ? error.message : String(error),
    operationId,
  });
}

