/**
 * IndexedDB persistence for bulk manifests, checkpoints, and idempotency records.
 */

import { openDB, type DBSchema, type IDBPDatabase } from 'idb';
import type {
  BulkIdempotencyRecord,
  BulkManifest,
  BulkRunCheckpoint,
  BulkRunReceipt,
} from '../../types/bulkOperationsPlanner';

const DB_NAME = 'stellar-bulk-operations';
const DB_VERSION = 1;

interface BulkDbSchema extends DBSchema {
  manifests: { key: string; value: BulkManifest; indexes: { updatedAt: string; network: string } };
  checkpoints: { key: string; value: BulkRunCheckpoint; indexes: { manifestId: string; status: string } };
  receipts: { key: string; value: BulkRunReceipt; indexes: { manifestId: string } };
  idempotency: { key: string; value: BulkIdempotencyRecord };
}

let dbPromise: Promise<IDBPDatabase<BulkDbSchema>> | null = null;

function openBulkDatabase(): Promise<IDBPDatabase<BulkDbSchema>> {
  if (dbPromise) return dbPromise;
  dbPromise = openDB<BulkDbSchema>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('manifests')) {
        const store = db.createObjectStore('manifests', { keyPath: 'manifestId' });
        store.createIndex('updatedAt', 'updatedAt');
        store.createIndex('network', 'network');
      }
      if (!db.objectStoreNames.contains('checkpoints')) {
        const store = db.createObjectStore('checkpoints', { keyPath: 'runId' });
        store.createIndex('manifestId', 'manifestId');
        store.createIndex('status', 'status');
      }
      if (!db.objectStoreNames.contains('receipts')) {
        const store = db.createObjectStore('receipts', { keyPath: 'runId' });
        store.createIndex('manifestId', 'manifestId');
      }
      if (!db.objectStoreNames.contains('idempotency')) {
        db.createObjectStore('idempotency', { keyPath: 'idempotencyKey' });
      }
    },
  });
  return dbPromise;
}

export interface BulkRepository {
  saveManifest(manifest: BulkManifest): Promise<void>;
  getManifest(id: string): Promise<BulkManifest | undefined>;
  listManifests(): Promise<BulkManifest[]>;
  deleteManifest(id: string): Promise<boolean>;
  saveCheckpoint(checkpoint: BulkRunCheckpoint): Promise<void>;
  getCheckpoint(runId: string): Promise<BulkRunCheckpoint | undefined>;
  getLatestCheckpoint(manifestId: string): Promise<BulkRunCheckpoint | undefined>;
  saveReceipt(receipt: BulkRunReceipt): Promise<void>;
  getReceipt(runId: string): Promise<BulkRunReceipt | undefined>;
  claimCheckpoint(runId: string, leaseMs: number): Promise<BulkRunCheckpoint | undefined>;
  putIdempotency(record: BulkIdempotencyRecord): Promise<void>;
  getIdempotency(key: string): Promise<BulkIdempotencyRecord | undefined>;
}

export class IndexedDbBulkRepository implements BulkRepository {
  async saveManifest(manifest: BulkManifest): Promise<void> {
    const db = await openBulkDatabase();
    await db.put('manifests', manifest);
  }

  async getManifest(id: string): Promise<BulkManifest | undefined> {
    const db = await openBulkDatabase();
    return db.get('manifests', id);
  }

  async listManifests(): Promise<BulkManifest[]> {
    const db = await openBulkDatabase();
    const all = await db.getAll('manifests');
    return all.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  }

  async deleteManifest(id: string): Promise<boolean> {
    const db = await openBulkDatabase();
    const existing = await db.get('manifests', id);
    if (!existing) return false;
    await db.delete('manifests', id);
    return true;
  }

  async saveCheckpoint(checkpoint: BulkRunCheckpoint): Promise<void> {
    const db = await openBulkDatabase();
    await db.put('checkpoints', { ...checkpoint, updatedAt: Date.now() });
  }

  async getCheckpoint(runId: string): Promise<BulkRunCheckpoint | undefined> {
    const db = await openBulkDatabase();
    return db.get('checkpoints', runId);
  }

  async getLatestCheckpoint(manifestId: string): Promise<BulkRunCheckpoint | undefined> {
    const db = await openBulkDatabase();
    const all = await db.getAllFromIndex('checkpoints', 'manifestId', manifestId);
    return all.sort((a, b) => b.updatedAt - a.updatedAt)[0];
  }

  async saveReceipt(receipt: BulkRunReceipt): Promise<void> {
    const db = await openBulkDatabase();
    await db.put('receipts', receipt);
  }

  async getReceipt(runId: string): Promise<BulkRunReceipt | undefined> {
    const db = await openBulkDatabase();
    return db.get('receipts', runId);
  }

  async claimCheckpoint(runId: string, leaseMs: number): Promise<BulkRunCheckpoint | undefined> {
    const db = await openBulkDatabase();
    const tx = db.transaction('checkpoints', 'readwrite');
    const store = tx.objectStore('checkpoints');
    const existing = await store.get(runId);
    if (!existing) return undefined;
    const now = Date.now();
    if (existing.leaseUntil && existing.leaseUntil > now) return undefined;
    const claimed = { ...existing, leaseUntil: now + leaseMs, status: 'running' as const, updatedAt: now };
    await store.put(claimed);
    await tx.done;
    return claimed;
  }

  async putIdempotency(record: BulkIdempotencyRecord): Promise<void> {
    const db = await openBulkDatabase();
    await db.put('idempotency', record);
  }

  async getIdempotency(key: string): Promise<BulkIdempotencyRecord | undefined> {
    const db = await openBulkDatabase();
    return db.get('idempotency', key);
  }
}

export class InMemoryBulkRepository implements BulkRepository {
  private manifests = new Map<string, BulkManifest>();
  private checkpoints = new Map<string, BulkRunCheckpoint>();
  private receipts = new Map<string, BulkRunReceipt>();
  private idempotency = new Map<string, BulkIdempotencyRecord>();

  async saveManifest(manifest: BulkManifest): Promise<void> {
    this.manifests.set(manifest.manifestId, manifest);
  }
  async getManifest(id: string): Promise<BulkManifest | undefined> {
    return this.manifests.get(id);
  }
  async listManifests(): Promise<BulkManifest[]> {
    return [...this.manifests.values()].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  }
  async deleteManifest(id: string): Promise<boolean> {
    return this.manifests.delete(id);
  }
  async saveCheckpoint(checkpoint: BulkRunCheckpoint): Promise<void> {
    this.checkpoints.set(checkpoint.runId, { ...checkpoint, updatedAt: Date.now() });
  }
  async getCheckpoint(runId: string): Promise<BulkRunCheckpoint | undefined> {
    return this.checkpoints.get(runId);
  }
  async getLatestCheckpoint(manifestId: string): Promise<BulkRunCheckpoint | undefined> {
    return [...this.checkpoints.values()]
      .filter((c) => c.manifestId === manifestId)
      .sort((a, b) => b.updatedAt - a.updatedAt)[0];
  }
  async saveReceipt(receipt: BulkRunReceipt): Promise<void> {
    this.receipts.set(receipt.runId, receipt);
  }
  async getReceipt(runId: string): Promise<BulkRunReceipt | undefined> {
    return this.receipts.get(runId);
  }
  async claimCheckpoint(runId: string, leaseMs: number): Promise<BulkRunCheckpoint | undefined> {
    const existing = this.checkpoints.get(runId);
    if (!existing) return undefined;
    const now = Date.now();
    if (existing.leaseUntil && existing.leaseUntil > now) return undefined;
    const claimed = { ...existing, leaseUntil: now + leaseMs, status: 'running' as const, updatedAt: now };
    this.checkpoints.set(runId, claimed);
    return claimed;
  }
  async putIdempotency(record: BulkIdempotencyRecord): Promise<void> {
    this.idempotency.set(record.idempotencyKey, record);
  }
  async getIdempotency(key: string): Promise<BulkIdempotencyRecord | undefined> {
    return this.idempotency.get(key);
  }
}

export const bulkRepository = new IndexedDbBulkRepository();

export async function resetBulkDatabaseForTests(): Promise<void> {
  dbPromise = null;
  if (typeof indexedDB !== 'undefined') {
    await new Promise<void>((resolve, reject) => {
      const request = indexedDB.deleteDatabase(DB_NAME);
      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }
}
