import { useRef, type ChangeEvent, type CSSProperties } from 'react';
import { Download, Pause, Play, RefreshCw, Upload, X } from 'lucide-react';
import useBulkOperationsPlanner from '../../hooks/useBulkOperationsPlanner';
import { useStore } from '../../lib/store';
import BulkImportPanel from './BulkImportPanel';
import BulkPreviewPanel from './BulkPreviewPanel';
import BulkPlanPanel from './BulkPlanPanel';
import BulkExecutePanel from './BulkExecutePanel';
import BulkReceiptsPanel from './BulkReceiptsPanel';
import BulkSettingsPanel from './BulkSettingsPanel';

const panel: CSSProperties = {
  background: 'var(--bg-card)',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-lg)',
  padding: 18,
};

const button: CSSProperties = {
  minHeight: 36,
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 7,
  padding: '7px 12px',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-md)',
  background: 'var(--bg-elevated)',
  color: 'var(--text-secondary)',
  cursor: 'pointer',
  fontSize: 11,
};

const tabs = [
  { id: 'import', label: 'Import' },
  { id: 'preview', label: 'Preview' },
  { id: 'plan', label: 'Plan' },
  { id: 'execute', label: 'Execute' },
  { id: 'receipts', label: 'Receipts' },
  { id: 'settings', label: 'Settings' },
] as const;

export default function BulkOperationsDashboard() {
  const { connectedAddress, network } = useStore();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const bulk = useBulkOperationsPlanner(connectedAddress, network);

  const handleImport = (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) void bulk.importJsonFile(file);
    event.target.value = '';
  };

  if (!connectedAddress) {
    return (
      <div style={panel}>
        <h2 style={{ margin: 0, fontSize: 18 }}>Bulk operations planner</h2>
        <p style={{ color: 'var(--text-muted)', marginTop: 12 }}>
          Connect an account to import, plan, and execute dependency-aware bulk operations.
        </p>
      </div>
    );
  }

  return (
    <div style={{ display: 'grid', gap: 16 }}>
      <header style={{ ...panel, display: 'grid', gap: 12 }}>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h2 style={{ margin: 0, fontSize: 18 }}>Resumable bulk operations</h2>
            <p style={{ margin: '6px 0 0', fontSize: 12, color: 'var(--text-muted)' }}>
              Dependency-aware planning with checkpointed signing, simulation, and sanitized export. Invalid rows are never silently skipped.
            </p>
          </div>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            <button type="button" style={button} onClick={() => void bulk.refreshManifests()}>
              <RefreshCw size={14} aria-hidden />
              Refresh
            </button>
            <button type="button" style={button} onClick={() => fileInputRef.current?.click()}>
              <Upload size={14} aria-hidden />
              Import JSON
            </button>
            <input ref={fileInputRef} type="file" accept=".json" hidden onChange={handleImport} />
          </div>
        </div>

        {bulk.error && (
          <div role="alert" style={{ color: 'var(--red)', fontSize: 12 }}>
            {bulk.error.message}
          </div>
        )}
        {bulk.message && (
          <div role="status" style={{ color: 'var(--cyan)', fontSize: 12 }}>
            {bulk.message}
          </div>
        )}

        <nav aria-label="Bulk planner views" style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
          {tabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              aria-current={bulk.view === tab.id ? 'page' : undefined}
              style={{
                ...button,
                background: bulk.view === tab.id ? 'var(--accent-muted)' : button.background,
                color: bulk.view === tab.id ? 'var(--accent)' : button.color,
              }}
              onClick={() => bulk.setView(tab.id)}
            >
              {tab.label}
            </button>
          ))}
        </nav>
      </header>

      {bulk.loading ? (
        <div style={panel} aria-busy="true">Loading bulk manifests…</div>
      ) : (
        <>
          {bulk.view === 'import' && (
            <BulkImportPanel
              manifests={bulk.manifests}
              activeManifestId={bulk.activeManifestId}
              onSelect={bulk.setActiveManifestId}
              onImportCsv={bulk.importCsv}
              onLoadDemoCsv={bulk.loadDemoCsv}
              onPlan={() => bulk.activeManifest && bulk.runPlanning(bulk.activeManifest)}
            />
          )}
          {bulk.view === 'preview' && <BulkPreviewPanel preview={bulk.preview} validation={bulk.validation} />}
          {bulk.view === 'plan' && (
            <BulkPlanPanel
              manifest={bulk.activeManifest}
              plan={bulk.plan}
              validation={bulk.validation}
              onDryRun={bulk.dryRun}
              onApprove={() => bulk.setApproved(true)}
              approved={bulk.approved}
            />
          )}
          {bulk.view === 'execute' && (
            <BulkExecutePanel
              executing={bulk.executing}
              progress={bulk.progress}
              checkpoint={bulk.checkpoint}
              approved={bulk.approved}
              requireApproval={bulk.preferences.requireApproval}
              onExecute={() => void bulk.executePlan()}
              onPause={() => void bulk.pauseExecution()}
              onResume={() => void bulk.resumeExecution()}
              onCancel={() => void bulk.cancelExecution()}
            />
          )}
          {bulk.view === 'receipts' && (
            <BulkReceiptsPanel receipt={bulk.receipt} checkpoint={bulk.checkpoint} onExport={bulk.exportReconciliation} />
          )}
          {bulk.view === 'settings' && (
            <BulkSettingsPanel preferences={bulk.preferences} onChange={bulk.setPreferences} />
          )}
        </>
      )}

      {bulk.activeManifest && (
        <footer style={{ ...panel, display: 'flex', flexWrap: 'wrap', gap: 8 }}>
          <button type="button" style={button} onClick={() => bulk.activeManifest && bulk.runPlanning(bulk.activeManifest)}>
            Plan
          </button>
          <button type="button" style={button} onClick={() => void bulk.executePlan()} disabled={bulk.executing}>
            <Play size={14} aria-hidden />
            Execute
          </button>
          <button type="button" style={button} onClick={() => void bulk.pauseExecution()} disabled={!bulk.executing}>
            <Pause size={14} aria-hidden />
            Pause
          </button>
          <button type="button" style={button} onClick={() => void bulk.cancelExecution()}>
            <X size={14} aria-hidden />
            Cancel
          </button>
          <button type="button" style={button} onClick={() => void bulk.exportManifest()}>
            <Download size={14} aria-hidden />
            Export
          </button>
        </footer>
      )}
    </div>
  );
}
