import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { NetworkName } from '../lib/stellar';
import {
  bulkRepository,
  buildDemoManifest,
  BulkPlannerError,
  createSimulatedExecutor,
  dryRunPlan,
  exportManifestJson,
  exportReconciliationCsv,
  importCsvManifest,
  importCsvPreview,
  planManifest,
  readBulkImportFile,
  toBulkPlannerError,
  type BulkExecutionPlan,
  type BulkImportPreview,
  type BulkManifest,
  type BulkProgressEvent,
  type BulkRunCheckpoint,
  type BulkRunReceipt,
  type BulkValidationReport,
  type BulkCsvImportOptions,
} from '../lib/bulkOperationsPlanner';
import { DEMO_CSV_PAYMENTS } from '../lib/bulkOperationsPlanner/fixtures';

const PREFS_KEY = 'stellar:bulk-operations:preferences';

export interface BulkPlannerPreferences {
  concurrency: number;
  maxOperationsPerTx: number;
  simulateBeforeExecute: boolean;
  requireApproval: boolean;
  autoRetry: boolean;
}

const defaultPreferences: BulkPlannerPreferences = {
  concurrency: 1,
  maxOperationsPerTx: 100,
  simulateBeforeExecute: true,
  requireApproval: true,
  autoRetry: true,
};

function loadPreferences(): BulkPlannerPreferences {
  try {
    const stored = JSON.parse(localStorage.getItem(PREFS_KEY) ?? '{}') as Partial<BulkPlannerPreferences>;
    return { ...defaultPreferences, ...stored };
  } catch {
    return defaultPreferences;
  }
}

export type BulkPlannerView = 'import' | 'preview' | 'plan' | 'execute' | 'receipts' | 'settings';

export default function useBulkOperationsPlanner(accountId: string | null, network: NetworkName) {
  const [manifests, setManifests] = useState<BulkManifest[]>([]);
  const [activeManifestId, setActiveManifestId] = useState<string | null>(null);
  const [plan, setPlan] = useState<BulkExecutionPlan | null>(null);
  const [validation, setValidation] = useState<BulkValidationReport | null>(null);
  const [preview, setPreview] = useState<BulkImportPreview | null>(null);
  const [checkpoint, setCheckpoint] = useState<BulkRunCheckpoint | null>(null);
  const [receipt, setReceipt] = useState<BulkRunReceipt | null>(null);
  const [loading, setLoading] = useState(true);
  const [executing, setExecuting] = useState(false);
  const [progress, setProgress] = useState<BulkProgressEvent | null>(null);
  const [error, setError] = useState<BulkPlannerError | null>(null);
  const [message, setMessage] = useState('');
  const [view, setView] = useState<BulkPlannerView>('import');
  const [preferences, setPreferencesState] = useState<BulkPlannerPreferences>(loadPreferences);
  const [approved, setApproved] = useState(false);
  const controller = useRef<AbortController | null>(null);
  const executor = useMemo(() => createSimulatedExecutor(), []);

  const activeManifest = useMemo(
    () => manifests.find((m) => m.manifestId === activeManifestId) ?? null,
    [manifests, activeManifestId]
  );

  const refreshManifests = useCallback(async () => {
    setLoading(true);
    try {
      const all = await bulkRepository.listManifests();
      if (all.length === 0 && accountId) {
        const demo = buildDemoManifest();
        await bulkRepository.saveManifest(demo);
        setManifests([demo]);
        setActiveManifestId(demo.manifestId);
      } else {
        setManifests(all);
        if (!activeManifestId && all[0]) setActiveManifestId(all[0].manifestId);
      }
    } catch (err) {
      setError(toBulkPlannerError(err));
    } finally {
      setLoading(false);
    }
  }, [accountId, activeManifestId]);

  useEffect(() => {
    void refreshManifests();
  }, [refreshManifests]);

  const setPreferences = useCallback((next: Partial<BulkPlannerPreferences>) => {
    setPreferencesState((prev) => {
      const merged = { ...prev, ...next };
      localStorage.setItem(PREFS_KEY, JSON.stringify(merged));
      return merged;
    });
  }, []);

  const runPlanning = useCallback(
    (manifest: BulkManifest) => {
      const result = planManifest(manifest, accountId ? { [accountId]: 1_000_001 } : {});
      setValidation(result.validation);
      setPlan(result.plan);
      if (!result.validation.valid) {
        setError(new BulkPlannerError({ code: 'VALIDATION_FAILED', message: result.error ?? 'Validation failed.' }));
      } else {
        setError(null);
        setMessage(result.plan ? `Plan ready: ${result.plan.packs.length} packs.` : 'Planning failed.');
      }
      setView('plan');
    },
    [accountId]
  );

  const importCsv = useCallback(
    (text: string, label: string, options: BulkCsvImportOptions) => {
      if (!accountId) {
        setError(new BulkPlannerError({ code: 'NO_ACCOUNT', message: 'Connect an account to import bulk operations.' }));
        return;
      }
      const previewResult = importCsvPreview(text, accountId, options);
      setPreview(previewResult);
      setValidation(previewResult.validation);
      setView('preview');
      if (previewResult.validation.valid) {
        const manifest = importCsvManifest(text, label, network, accountId, options);
        void bulkRepository.saveManifest(manifest).then(async () => {
          await refreshManifests();
          setActiveManifestId(manifest.manifestId);
          setMessage(`Imported ${previewResult.operations.length} operations.`);
        });
      }
    },
    [accountId, network, refreshManifests]
  );

  const loadDemoCsv = useCallback(() => {
    importCsv(DEMO_CSV_PAYMENTS, 'CSV import demo', {
      hasHeader: true,
      mapping: {
        family: 'payment',
        columns: {
          externalRef: 'externalRef',
          destination: 'destination',
          amount: 'amount',
          assetType: 'assetType',
        },
      },
    });
  }, [importCsv]);

  const importJsonFile = useCallback(
    async (file: File) => {
      const result = await readBulkImportFile(file);
      if (result.ok === false) {
        setError(new BulkPlannerError({ code: 'IMPORT_FAILED', message: result.message }));
        return;
      }
      await bulkRepository.saveManifest(result.manifest);
      await refreshManifests();
      setActiveManifestId(result.manifest.manifestId);
      runPlanning(result.manifest);
    },
    [refreshManifests, runPlanning]
  );

  const executePlan = useCallback(async () => {
    if (!activeManifest || !plan) return;
    if (preferences.requireApproval && !approved) {
      setError(new BulkPlannerError({ code: 'APPROVAL_REQUIRED', message: 'Approve the plan before execution.' }));
      return;
    }

    controller.current?.abort();
    controller.current = new AbortController();
    setExecuting(true);
    setError(null);

    const runId = checkpoint?.runId ?? `run-${Date.now()}`;
    const baseCheckpoint =
      checkpoint ??
      executor.createCheckpoint(runId, activeManifest, plan, undefined, 'running');

    try {
      const result = await executor.execute(activeManifest, plan, baseCheckpoint, network, {
        simulateFirst: preferences.simulateBeforeExecute,
        signal: controller.current.signal,
        onProgress: setProgress,
      });
      setCheckpoint(result.checkpoint);
      await bulkRepository.saveCheckpoint(result.checkpoint);
      if (result.receipt) {
        setReceipt(result.receipt);
        await bulkRepository.saveReceipt(result.receipt);
        setMessage(`Execution complete: ${result.receipt.successful} succeeded, ${result.receipt.failed} failed.`);
        setView('receipts');
      }
    } catch (err) {
      setError(toBulkPlannerError(err));
    } finally {
      setExecuting(false);
      setProgress(null);
    }
  }, [activeManifest, plan, checkpoint, preferences, approved, executor, network]);

  const pauseExecution = useCallback(async () => {
    if (!checkpoint) return;
    const paused = executor.pause(checkpoint);
    setCheckpoint(paused);
    await bulkRepository.saveCheckpoint(paused);
    setMessage('Execution paused.');
  }, [checkpoint, executor]);

  const resumeExecution = useCallback(async () => {
    if (!checkpoint) return;
    const resumed = executor.resume(checkpoint);
    setCheckpoint(resumed);
    await bulkRepository.saveCheckpoint(resumed);
    setMessage('Execution resumed.');
    await executePlan();
  }, [checkpoint, executor, executePlan]);

  const cancelExecution = useCallback(async () => {
    controller.current?.abort();
    if (!checkpoint) return;
    const cancelled = executor.cancel(checkpoint);
    setCheckpoint(cancelled);
    await bulkRepository.saveCheckpoint(cancelled);
    setExecuting(false);
    setMessage('Execution cancelled.');
  }, [checkpoint, executor]);

  const exportManifest = useCallback(async () => {
    if (!activeManifest) return;
    const json = exportManifestJson(activeManifest, checkpoint ?? undefined);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `bulk-manifest-${activeManifest.label.replace(/\s+/g, '-')}.json`;
    anchor.click();
    URL.revokeObjectURL(url);
  }, [activeManifest, checkpoint]);

  const exportReconciliation = useCallback(() => {
    if (!activeManifest || !checkpoint) return;
    const csv = exportReconciliationCsv(checkpoint, activeManifest);
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = 'bulk-reconciliation.csv';
    anchor.click();
    URL.revokeObjectURL(url);
  }, [activeManifest, checkpoint]);

  const dryRun = useCallback(() => {
    if (!activeManifest) return;
    const result = dryRunPlan(activeManifest);
    setValidation(result.validation);
    setMessage(result.summary);
  }, [activeManifest]);

  return {
    manifests,
    activeManifest,
    activeManifestId,
    setActiveManifestId,
    plan,
    validation,
    preview,
    checkpoint,
    receipt,
    loading,
    executing,
    progress,
    error,
    message,
    setMessage,
    view,
    setView,
    preferences,
    setPreferences,
    approved,
    setApproved,
    refreshManifests,
    runPlanning,
    importCsv,
    loadDemoCsv,
    importJsonFile,
    executePlan,
    pauseExecution,
    resumeExecution,
    cancelExecution,
    exportManifest,
    exportReconciliation,
    dryRun,
  };
}
