/**
 * Manifest builder, planner orchestration, and dry-run simulation hooks.
 */

import type {
  BulkDependencyEdge,
  BulkExecutionPlan,
  BulkManifest,
  BulkOperationSpec,
  BulkValidationReport,
} from '../../types/bulkOperationsPlanner';
import {
  BULK_MANIFEST_FORMAT_KIND,
  BULK_MANIFEST_SCHEMA_VERSION,
} from '../../types/bulkOperationsPlanner';
import { stableCanonicalJson } from './canonicalize';
import { buildExecutionPlan } from './packing';
import { validateManifestOperations } from './validation';

function fnv1a(input: string): string {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

export interface BuildManifestParams {
  label: string;
  network: string;
  operations: BulkOperationSpec[];
  dependencyEdges?: BulkDependencyEdge[];
  defaults?: Partial<BulkManifest['defaults']>;
}

export function buildManifest(params: BuildManifestParams): BulkManifest {
  const now = new Date().toISOString();
  const manifestId = `manifest-${fnv1a(`${params.label}:${now}`)}`;
  const payload = {
    manifestId,
    label: params.label,
    network: params.network,
    operations: params.operations,
    dependencyEdges: params.dependencyEdges ?? [],
  };

  return {
    formatKind: BULK_MANIFEST_FORMAT_KIND,
    schemaVersion: BULK_MANIFEST_SCHEMA_VERSION,
    manifestId,
    label: params.label,
    network: params.network,
    createdAt: now,
    updatedAt: now,
    operations: params.operations,
    dependencyEdges: params.dependencyEdges ?? [],
    defaults: {
      maxRetries: 3,
      timeoutMs: 30_000,
      concurrency: 1,
      maxOperationsPerTx: 100,
      ...params.defaults,
    },
    checksum: fnv1a(stableCanonicalJson(payload)),
  };
}

export interface PlanResult {
  manifest: BulkManifest;
  validation: BulkValidationReport;
  plan: BulkExecutionPlan | null;
  error?: string;
}

export function planManifest(
  manifest: BulkManifest,
  startSequences: Record<string, number> = {}
): PlanResult {
  const validation = validateManifestOperations(manifest.operations, manifest.dependencyEdges);
  if (!validation.valid) {
    return { manifest, validation, plan: null, error: 'Manifest validation failed.' };
  }

  const planResult = buildExecutionPlan(manifest, {
    maxOperationsPerTx: manifest.defaults.maxOperationsPerTx,
    startSequences,
    concurrencyByAccount: Object.fromEntries(
      [...new Set(manifest.operations.map((op) => op.sourceAccount))].map((account) => [
        account,
        manifest.defaults.concurrency,
      ])
    ),
  });

  if (planResult.ok === false) {
    return { manifest, validation, plan: null, error: planResult.error };
  }

  return { manifest, validation, plan: planResult.plan };
}

export function dryRunPlan(manifest: BulkManifest, startSequences: Record<string, number> = {}): {
  validation: BulkValidationReport;
  summary: string;
  packs: number;
  operations: number;
} {
  const result = planManifest(manifest, startSequences);
  return {
    validation: result.validation,
    summary: result.plan ? `Dry run: ${result.plan.packs.length} packs for ${result.plan.topologicalOrder.length} operations` : result.error ?? 'Planning failed',
    packs: result.plan?.packs.length ?? 0,
    operations: manifest.operations.length,
  };
}

export function mergeManifestOperations(
  manifest: BulkManifest,
  additional: BulkOperationSpec[]
): BulkManifest {
  const operations = [...manifest.operations, ...additional];
  return buildManifest({
    label: manifest.label,
    network: manifest.network,
    operations,
    dependencyEdges: manifest.dependencyEdges,
    defaults: manifest.defaults,
  });
}

export function updateManifestChecksum(manifest: BulkManifest): BulkManifest {
  const payload = {
    manifestId: manifest.manifestId,
    label: manifest.label,
    network: manifest.network,
    operations: manifest.operations,
    dependencyEdges: manifest.dependencyEdges,
  };
  return {
    ...manifest,
    updatedAt: new Date().toISOString(),
    checksum: fnv1a(stableCanonicalJson(payload)),
  };
}

export function verifyManifestChecksum(manifest: BulkManifest): boolean {
  const payload = {
    manifestId: manifest.manifestId,
    label: manifest.label,
    network: manifest.network,
    operations: manifest.operations,
    dependencyEdges: manifest.dependencyEdges,
  };
  return fnv1a(stableCanonicalJson(payload)) === manifest.checksum;
}

export function filterOperationsByStatus(
  operations: BulkOperationSpec[],
  states: Map<string, { status: string }>,
  statuses: string[]
): BulkOperationSpec[] {
  return operations.filter((op) => statuses.includes(states.get(op.id)?.status ?? 'draft'));
}

export function buildDependencyEdgesFromRefs(
  operations: BulkOperationSpec[],
  refs: Array<{ fromRef: string; toRef: string; reason?: string }>
): BulkDependencyEdge[] {
  const byRef = new Map<string, string>();
  for (const op of operations) {
    if (op.metadata.externalRef) byRef.set(op.metadata.externalRef, op.id);
  }

  const edges: BulkDependencyEdge[] = [];
  for (const ref of refs) {
    const fromId = byRef.get(ref.fromRef);
    const toId = byRef.get(ref.toRef);
    if (fromId && toId) {
      edges.push({ fromId, toId, reason: ref.reason });
    }
  }
  return edges;
}
