import type { CSSProperties } from 'react';
import type { BulkPlannerPreferences } from '../../hooks/useBulkOperationsPlanner';

const panel: CSSProperties = {
  background: 'var(--bg-card)',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-lg)',
  padding: 18,
};

interface Props {
  preferences: BulkPlannerPreferences;
  onChange: (next: Partial<BulkPlannerPreferences>) => void;
}

export default function BulkSettingsPanel({ preferences, onChange }: Props) {
  return (
    <div style={panel}>
      <h3 style={{ margin: '0 0 12px', fontSize: 14 }}>Planner settings</h3>
      <div style={{ display: 'grid', gap: 12, maxWidth: 420, fontSize: 12 }}>
        <label style={{ display: 'grid', gap: 4 }}>
          Concurrency per account
          <input
            type="number"
            min={1}
            max={5}
            value={preferences.concurrency}
            onChange={(e) => onChange({ concurrency: Number(e.target.value) })}
            aria-label="Concurrency"
            style={{ padding: 8, borderRadius: 'var(--radius-md)', border: '1px solid var(--border)', background: 'var(--bg-elevated)', color: 'inherit' }}
          />
        </label>
        <label style={{ display: 'grid', gap: 4 }}>
          Max operations per transaction
          <input
            type="number"
            min={1}
            max={100}
            value={preferences.maxOperationsPerTx}
            onChange={(e) => onChange({ maxOperationsPerTx: Number(e.target.value) })}
            aria-label="Max operations per transaction"
            style={{ padding: 8, borderRadius: 'var(--radius-md)', border: '1px solid var(--border)', background: 'var(--bg-elevated)', color: 'inherit' }}
          />
        </label>
        <label style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <input
            type="checkbox"
            checked={preferences.simulateBeforeExecute}
            onChange={(e) => onChange({ simulateBeforeExecute: e.target.checked })}
          />
          Simulate before execute
        </label>
        <label style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <input type="checkbox" checked={preferences.requireApproval} onChange={(e) => onChange({ requireApproval: e.target.checked })} />
          Require approval before execution
        </label>
        <label style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <input type="checkbox" checked={preferences.autoRetry} onChange={(e) => onChange({ autoRetry: e.target.checked })} />
          Auto-retry retryable failures
        </label>
      </div>

      <div style={{ marginTop: 16, fontSize: 12, color: 'var(--text-muted)' }}>
        <p style={{ margin: '0 0 8px' }}>Security notes:</p>
        <ul style={{ margin: 0, paddingLeft: 18 }}>
          <li>Secret keys are never persisted in manifests or checkpoints.</li>
          <li>Non-idempotent failures require authoritative transaction-state checks before retry.</li>
          <li>Exports are sanitized by default.</li>
        </ul>
      </div>
    </div>
  );
}
