import { useState, type CSSProperties } from 'react';
import type { BulkManifest } from '../../types/bulkOperationsPlanner';
import type { BulkCsvImportOptions } from '../../types/bulkOperationsPlanner';

const panel: CSSProperties = {
  background: 'var(--bg-card)',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-lg)',
  padding: 18,
};

const button: CSSProperties = {
  minHeight: 36,
  display: 'inline-flex',
  alignItems: 'center',
  gap: 7,
  padding: '7px 12px',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-md)',
  background: 'var(--bg-elevated)',
  color: 'var(--text-secondary)',
  cursor: 'pointer',
  fontSize: 11,
};

interface Props {
  manifests: BulkManifest[];
  activeManifestId: string | null;
  onSelect: (id: string) => void;
  onImportCsv: (text: string, label: string, options: BulkCsvImportOptions) => void;
  onLoadDemoCsv: () => void;
  onPlan: () => void;
}

export default function BulkImportPanel({ manifests, activeManifestId, onSelect, onImportCsv, onLoadDemoCsv, onPlan }: Props) {
  const [csvText, setCsvText] = useState('');
  const [label, setLabel] = useState('Imported bulk manifest');

  return (
    <div style={{ display: 'grid', gap: 16 }}>
      <div style={panel}>
        <h3 style={{ margin: '0 0 12px', fontSize: 14 }}>CSV import</h3>
        <label style={{ display: 'grid', gap: 6, fontSize: 12 }}>
          Manifest label
          <input
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            aria-label="Manifest label"
            style={{ padding: 8, borderRadius: 'var(--radius-md)', border: '1px solid var(--border)', background: 'var(--bg-elevated)', color: 'inherit' }}
          />
        </label>
        <label style={{ display: 'grid', gap: 6, fontSize: 12, marginTop: 12 }}>
          CSV payload
          <textarea
            value={csvText}
            onChange={(e) => setCsvText(e.target.value)}
            aria-label="CSV payload"
            rows={8}
            style={{ padding: 8, borderRadius: 'var(--radius-md)', border: '1px solid var(--border)', background: 'var(--bg-elevated)', color: 'inherit', fontFamily: 'monospace' }}
          />
        </label>
        <div style={{ display: 'flex', gap: 8, marginTop: 12, flexWrap: 'wrap' }}>
          <button
            type="button"
            style={button}
            onClick={() =>
              onImportCsv(csvText, label, {
                hasHeader: true,
                mapping: {
                  family: 'payment',
                  columns: { externalRef: 'externalRef', destination: 'destination', amount: 'amount', assetType: 'assetType' },
                },
              })
            }
          >
            Preview import
          </button>
          <button type="button" style={button} onClick={onLoadDemoCsv}>
            Load demo CSV
          </button>
        </div>
      </div>

      <div style={panel}>
        <h3 style={{ margin: '0 0 12px', fontSize: 14 }}>Saved manifests</h3>
        <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'grid', gap: 8 }}>
          {manifests.map((manifest) => (
            <li key={manifest.manifestId}>
              <button
                type="button"
                onClick={() => onSelect(manifest.manifestId)}
                aria-pressed={activeManifestId === manifest.manifestId}
                style={{
                  width: '100%',
                  textAlign: 'left',
                  padding: 10,
                  borderRadius: 'var(--radius-md)',
                  border: `1px solid ${activeManifestId === manifest.manifestId ? 'var(--accent)' : 'var(--border)'}`,
                  background: 'var(--bg-elevated)',
                  color: 'inherit',
                  cursor: 'pointer',
                }}
              >
                <div style={{ fontWeight: 600 }}>{manifest.label}</div>
                <div style={{ fontSize: 11, color: 'var(--text-muted)' }}>
                  {manifest.operations.length} operations · {manifest.network}
                </div>
              </button>
            </li>
          ))}
        </ul>
        <button type="button" style={{ ...button, marginTop: 12 }} onClick={onPlan}>
          Plan selected manifest
        </button>
      </div>
    </div>
  );
}
