import type { CSSProperties } from 'react';
import type { BulkRunCheckpoint, BulkRunReceipt } from '../../types/bulkOperationsPlanner';

const panel: CSSProperties = {
  background: 'var(--bg-card)',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-lg)',
  padding: 18,
};

const button: CSSProperties = {
  minHeight: 36,
  padding: '7px 12px',
  border: '1px solid var(--border)',
  borderRadius: 'var(--radius-md)',
  background: 'var(--bg-elevated)',
  cursor: 'pointer',
  fontSize: 11,
};

interface Props {
  receipt: BulkRunReceipt | null;
  checkpoint: BulkRunCheckpoint | null;
  onExport: () => void;
}

export default function BulkReceiptsPanel({ receipt, checkpoint, onExport }: Props) {
  return (
    <div style={{ display: 'grid', gap: 16 }}>
      <div style={panel}>
        <h3 style={{ margin: '0 0 12px', fontSize: 14 }}>Execution receipts</h3>
        {receipt ? (
          <dl style={{ display: 'grid', gridTemplateColumns: '140px 1fr', gap: 8, fontSize: 12, margin: 0 }}>
            <dt style={{ color: 'var(--text-muted)' }}>Run ID</dt>
            <dd style={{ margin: 0 }}>{receipt.runId}</dd>
            <dt style={{ color: 'var(--text-muted)' }}>Successful</dt>
            <dd style={{ margin: 0 }}>{receipt.successful}</dd>
            <dt style={{ color: 'var(--text-muted)' }}>Failed</dt>
            <dd style={{ margin: 0 }}>{receipt.failed}</dd>
            <dt style={{ color: 'var(--text-muted)' }}>Skipped</dt>
            <dd style={{ margin: 0 }}>{receipt.skipped}</dd>
            <dt style={{ color: 'var(--text-muted)' }}>Total fee</dt>
            <dd style={{ margin: 0 }}>{receipt.totalFee} stroops</dd>
          </dl>
        ) : (
          <p style={{ fontSize: 12, color: 'var(--text-muted)' }}>No receipt yet. Complete an execution run first.</p>
        )}
        <button type="button" style={{ ...button, marginTop: 12 }} onClick={onExport} disabled={!checkpoint}>
          Export reconciliation CSV
        </button>
      </div>

      {receipt && (
        <div style={panel}>
          <h4 style={{ margin: '0 0 12px', fontSize: 13 }}>Transaction hashes</h4>
          <ul style={{ margin: 0, paddingLeft: 18, fontSize: 12, fontFamily: 'monospace' }}>
            {receipt.transactionHashes.map((hash) => (
              <li key={hash}>{hash}</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
